/* Mode: Run Once for All Items. */
const books = $input.all().map(item => item.json);

const clean = value =>
  String(value ?? "").replace(/\s+/g, " ").trim();

const normalize = value =>
  clean(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[’‘]/g, "'")
    .toLowerCase();

const missingLabels = new Set([
  "",
  "non renseigne",
  "inconnu",
  "inconnue",
  "null",
  "undefined",
  "n/a",
  "sans genre",
  "sans auteur",
  "auteur inconnu",
  "sans editeur"
]);

function toNumber(value) {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : 0;
  }

  let text = clean(value).replace(/[\s\u00a0\u202f€]/g, "");

  if (!text) return 0;

  if (text.includes(",") && text.includes(".")) {
    text = text.lastIndexOf(",") > text.lastIndexOf(".")
      ? text.replace(/\./g, "").replace(",", ".")
      : text.replace(/,/g, "");
  } else {
    text = text.replace(",", ".");
  }

  const parsed = Number(text);
  return Number.isFinite(parsed) ? parsed : 0;
}

function toYear(value) {
  const match = clean(value).match(/\b([12]\d{3})\b/);
  return match ? Number(match[1]) : null;
}

function getLabels(value, fallback) {
  let values = value;

  if (
    typeof values === "string" &&
    values.trim().startsWith("[")
  ) {
    try {
      values = JSON.parse(values);
    } catch {}
  }

  if (!Array.isArray(values)) {
    values = [values];
  }

  const unique = new Map();

  for (const item of values) {
    const label = clean(
      item && typeof item === "object"
        ? item.name || item.labelFr || ""
        : item
    );

    const key = normalize(label);

    if (!missingLabels.has(key)) {
      unique.set(key, label);
    }
  }

  return unique.size ? [...unique.values()] : [fallback];
}

function addLabels(counter, labels) {
  for (const label of labels) {
    const key = normalize(label);
    const entry = counter.get(key) || { label, count: 0 };

    entry.count++;
    counter.set(key, entry);
  }
}

function sortCounts(counter) {
  return Object.fromEntries(
    [...counter.values()]
      .sort((a, b) =>
        b.count - a.count ||
        a.label.localeCompare(b.label, "fr")
      )
      .map(entry => [entry.label, entry.count])
  );
}

function createGroup() {
  return {
    total: 0,
    genres: new Map(),
    authors: new Map(),
    publishers: new Map(),
    decades: new Map(),
    withoutYear: 0
  };
}

function addBook(group, book, releaseYear) {
  group.total++;

  addLabels(
    group.genres,
    getLabels(book.genre, "Sans genre")
  );

  addLabels(
    group.authors,
    getLabels(book.auteur, "Auteur inconnu")
  );

  addLabels(
    group.publishers,
    getLabels(book.editeur, "Sans éditeur")
  );

  if (releaseYear === null) {
    group.withoutYear++;
  } else {
    const decade = Math.floor(releaseYear / 10) * 10;

    group.decades.set(
      decade,
      (group.decades.get(decade) || 0) + 1
    );
  }
}

function exportGroup(group) {
  const decades = Object.fromEntries(
    [...group.decades.entries()]
      .sort((a, b) => b[0] - a[0])
      .map(([decade, count]) => [decade + "s", count])
  );

  if (group.withoutYear > 0) {
    decades["Sans année"] = group.withoutYear;
  }

  return {
    Total: group.total,
    Genre: sortCounts(group.genres),
    Auteurs: sortCounts(group.authors),
    "Éditeurs": sortCounts(group.publishers),
    "Décennies": decades
  };
}

function createRange() {
  return {
    min: Infinity,
    max: -1,
    minTitle: "Aucun",
    maxTitle: "Aucun"
  };
}

function updateRange(range, pages, title) {
  if (pages < range.min) {
    range.min = pages;
    range.minTitle = title;
  }

  if (pages > range.max) {
    range.max = pages;
    range.maxTitle = title;
  }
}

function rangeText(range, side) {
  const pages =
    Number.isFinite(range[side]) && range[side] >= 0
      ? range[side]
      : 0;

  return range[side + "Title"] + " (" + pages + " p.)";
}

const ownedGroup = createGroup();
const wishGroup = createGroup();

const globalReadRange = createRange();
const ownedReadRange = createRange();

let ownedRead = 0;
let ownedUnread = 0;
let ownedReading = 0;
let unownedRead = 0;
let unclassified = 0;

let pagesRead = 0;
let collectionCents = 0;
let withoutYear = 0;

/* Keep separate editions even when they share the same id_unique. */
for (const book of books) {
  const status = normalize(book.statut);
  const title = clean(book.titre) || "Titre inconnu";

  const pages = Math.max(
    0,
    Math.trunc(toNumber(book.nb_pages))
  );

  const releaseYear = toYear(book.annee_sortie);

  /* Anchored ownership prevents "Non possédé" from matching. */
  const isOwned = /^possede(?:\s|$)/.test(status);

  /* Exact reading states exclude unread and in-progress books. */
  const isRead = [
    "possede et lu",
    "non possede mais lu",
    "non possede et lu"
  ].includes(status);

  const isReading = status === "possede et je lis";

  const isWish = [
    "liste de souhait",
    "liste de souhaits"
  ].includes(status);

  if (releaseYear === null) {
    withoutYear++;
  }

  if (isOwned) {
    addBook(ownedGroup, book, releaseYear);

    collectionCents += Math.round(
      Math.max(0, toNumber(book.Prix)) * 100
    );

    if (isRead) {
      ownedRead++;
    } else if (isReading) {
      ownedReading++;
    } else {
      ownedUnread++;
    }
  }

  if (isWish) {
    addBook(wishGroup, book, releaseYear);
  }

  if (isRead) {
    if (!isOwned) {
      unownedRead++;
    }

    pagesRead += pages;

    updateRange(globalReadRange, pages, title);

    if (isOwned) {
      updateRange(ownedReadRange, pages, title);
    }
  }

  if (!isOwned && !isWish && !isRead) {
    unclassified++;
  }
}

const totalRead = ownedRead + unownedRead;

const possession = exportGroup(ownedGroup);
const souhaits = exportGroup(wishGroup);

const donneesDominantes = {
  "En possession": possession,
  "Liste de souhait": souhaits
};

return [
  {
    json: {
      Pages: pagesRead,
      Prix: (collectionCents / 100).toFixed(2).replace(".", ","),

      "En possession (Total)": ownedGroup.total,
      "En possession et Lu": ownedRead,
      "En possession et Non lu": ownedUnread,
      "En possession et Je lis": ownedReading,
      "Non possédé et Lu": unownedRead,
      "Liste de souhait": wishGroup.total,
      "Non classé": unclassified,

      Livres_Total: books.length,
      Livres_Bibliotheque: ownedGroup.total,
      Livres_Lus_Total: totalRead,

      Moyenne_Pages:
        totalRead > 0
          ? Math.round(pagesRead / totalRead)
          : 0,

      Genre: "Roman",

      Global_Max: rangeText(globalReadRange, "max"),
      Global_Min: rangeText(globalReadRange, "min"),
      Bibli_Max: rangeText(ownedReadRange, "max"),
      Bibli_Min: rangeText(ownedReadRange, "min"),

      withoutYear,

      /* Preserve existing mappings with rankings restricted to owned books. */
      Genres: possession.Genre,
      Auteurs: possession.Auteurs,
      Editeurs: possession["Éditeurs"],
      Decennies: possession["Décennies"],

      donneesDominantes
    }
  }
];

const resultats = normalizeBrowserlessResult($input.first().json);

if (resultats.statut_session === "invalide") {
  throw new Error(resultats.erreur || "Session Bubble invalide");
}

const captures = resultats.captures || {};
const seriesMap = {};

function normalizeBrowserlessResult(value) {
  let data = value;

  if (typeof data === "string") {
    try {
      data = JSON.parse(data);
    } catch (error) {
      return {};
    }
  }

  if (data && typeof data.data === "string") {
    try {
      data = JSON.parse(data.data);
    } catch (error) {
      return {};
    }
  } else if (
    data &&
    data.data &&
    typeof data.data === "object" &&
    !data.captures
  ) {
    data = data.data;
  }

  return data || {};
}

function decodeHtml(value) {
  return String(value || "")
    .replace(/&nbsp;|&#160;|&#xA0;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/\s+/g, " ")
    .trim();
}

function parseCountPair(value) {
  const text = String(value || "");
  const match = text.match(/([0-9]+)(?:\s*\/\s*([0-9]+))?/);

  return {
    current: match ? parseInt(match[1], 10) : 0,
    total: match && match[2] ? parseInt(match[2], 10) : 0
  };
}

function ensureSerie(id, categorie) {
  if (!seriesMap[id]) {
    seriesMap[id] = {
      id_unique: id,
      titre: "Titre inconnu",
      categorie: categorie || "Autre",
      albums_possedes: 0,
      albums_lus_possedes: 0,
      albums_non_possedes_lu: 0,
      albums_manquants: 0,
      nb_dedicace: 0
    };
  }

  if (categorie && categorie !== "Autre") {
    seriesMap[id].categorie = categorie;
  } else if (!seriesMap[id].categorie) {
    seriesMap[id].categorie = "Autre";
  }

  return seriesMap[id];
}

function getTitle(block) {
  const patterns = [
    /<div[^>]*class="[^"]*tw:truncate[^"]*tw:font-bold[^"]*"[^>]*>\s*([^<]+?)\s*<\/div>/i,
    /<div[^>]*class="[^"]*font-bold[^"]*"[^>]*>\s*([^<]+?)\s*<\/div>/i,
    /fw-bold[^>]*>\s*([^<]+?)\s*<\/div>/i
  ];

  for (const pattern of patterns) {
    const match = block.match(pattern);

    if (match) {
      return decodeHtml(match[1]);
    }
  }

  return "Titre inconnu";
}

function getAlbumCount(block) {
  const patterns = [
    /<div[^>]*>\s*([0-9]+(?:\s*\/\s*[0-9]+)?)\s*<\/div>\s*<div[^>]*>\s*albums?\s*<\/div>/i,
    /([0-9]+(?:\s*\/\s*[0-9]+)?)\s+albums?/i
  ];

  for (const pattern of patterns) {
    const match = block.match(pattern);

    if (match) {
      return parseCountPair(match[1]);
    }
  }

  return {
    current: 0,
    total: 0
  };
}

function getReadCount(block) {
  const patterns = [
    /<div[^>]*>\s*([0-9]+(?:\s*\/\s*[0-9]+)?)\s*<\/div>\s*<div[^>]*>\s*lus?\s*<\/div>/i,
    /([0-9]+(?:\s*\/\s*[0-9]+)?)\s+lus?/i
  ];

  for (const pattern of patterns) {
    const match = block.match(pattern);

    if (match) {
      return parseCountPair(match[1]);
    }
  }

  return {
    current: 0,
    total: 0
  };
}

function getDedicaceCount(block) {
  const patterns = [
    /<div[^>]*>\s*([0-9]+)\s*<\/div>\s*<div[^>]*>\s*dédicaces?\s*<\/div>/i,
    /([0-9]+)\s+dédicaces?/i,
    /([0-9]+)\s+dédicace/i
  ];

  for (const pattern of patterns) {
    const match = block.match(pattern);

    if (match) {
      return parseInt(match[1], 10) || 0;
    }
  }

  return 0;
}

function scanSeriesLinks(html, callback) {
  if (!html) return;

  const morceaux = String(html).split('href="/');

  for (let i = 1; i < morceaux.length; i++) {
    const block = morceaux[i];

    const idMatch = block.match(/^[^"\/]+\/serie\/([a-zA-Z0-9]+)"/);

    if (!idMatch) continue;

    callback(idMatch[1], block);
  }
}

function parsePossessedCapture(captureKey, categorie) {
  const html = captures?.[captureKey]?.html || "";

  scanSeriesLinks(html, (id, block) => {
    const serie = ensureSerie(id, categorie);

    const titre = getTitle(block);

    if (titre && titre !== "Titre inconnu") {
      serie.titre = titre;
    }

    const albums = getAlbumCount(block);
    const lus = getReadCount(block);
    const dedicaces = getDedicaceCount(block);

    if (albums.current > 0) {
      serie.albums_possedes = Math.max(serie.albums_possedes, albums.current);
    }

    if (lus.current > 0) {
      serie.albums_lus_possedes = Math.max(serie.albums_lus_possedes, lus.current);
    }

    if (albums.total > 0) {
      const manquants = Math.max(albums.total - albums.current, 0);
      serie.albums_manquants = Math.max(serie.albums_manquants, manquants);
    }

    if (dedicaces > 0) {
      serie.nb_dedicace = Math.max(serie.nb_dedicace, dedicaces);
    }
  });
}

function parseNonPossessedReadCapture(captureKey, categorie) {
  const html = captures?.[captureKey]?.html || "";

  scanSeriesLinks(html, (id, block) => {
    const serie = ensureSerie(id, categorie);

    const titre = getTitle(block);

    if (titre && titre !== "Titre inconnu") {
      serie.titre = titre;
    }

    const lus = getReadCount(block);
    const albums = getAlbumCount(block);

    const nonPossedesLus = Math.max(lus.current, albums.current, 0);

    if (nonPossedesLus > 0) {
      serie.albums_non_possedes_lu = Math.max(
        serie.albums_non_possedes_lu,
        nonPossedesLus
      );
    }

    if (albums.total > 0) {
      const manquants = Math.max(albums.total - albums.current, 0);
      serie.albums_manquants = Math.max(serie.albums_manquants, manquants);
    }
  });
}

function parseDedicaceCapture(captureKey) {
  const html = captures?.[captureKey]?.html || "";

  scanSeriesLinks(html, (id, block) => {
    const serie = ensureSerie(id, null);

    const titre = getTitle(block);

    if (titre && titre !== "Titre inconnu") {
      serie.titre = titre;
    }

    const dedicaces = getDedicaceCount(block);
    const albums = getAlbumCount(block);

    const nbDedicace = Math.max(dedicaces, albums.current, 1);

    serie.nb_dedicace = Math.max(serie.nb_dedicace, nbDedicace);
  });
}

// First parse the complete library as Autre.
parsePossessedCapture("ALL_JAI", "Autre");
parseNonPossessedReadCapture("ALL_JAIPAS_LU", "Autre");

// Then add dedicated album information.
parseDedicaceCapture("ALL_DEDICACE");

// Then parse precise categories to reclassify series.
parsePossessedCapture("BD_JAI", "BD");
parseNonPossessedReadCapture("BD_JAIPAS_LU", "BD");

parsePossessedCapture("Comics_JAI", "Comics");
parseNonPossessedReadCapture("Comics_JAIPAS_LU", "Comics");

parsePossessedCapture("Mangas_JAI", "Mangas");
parseNonPossessedReadCapture("Mangas_JAIPAS_LU", "Mangas");

const lignes = Object.values(seriesMap)
  .filter(serie => serie.id_unique && serie.titre && serie.titre !== "Titre inconnu")
  .sort((a, b) => {
    const catCompare = String(a.categorie).localeCompare(String(b.categorie), "fr");

    if (catCompare !== 0) {
      return catCompare;
    }

    return String(a.titre).localeCompare(String(b.titre), "fr");
  })
  .map((serie) => {
    const albumsPossedes = serie.albums_possedes || 0;
    const albumsLusPossedes = serie.albums_lus_possedes || 0;
    const albumsNonPossedesLu = serie.albums_non_possedes_lu || 0;
    const albumsLusTotal = albumsLusPossedes + albumsNonPossedesLu;

    let statut = "Non classé";

    if (albumsPossedes > 0 && albumsNonPossedesLu > 0) {
      statut = "Partiellement possédé";
    } else if (albumsPossedes > 0) {
      if (albumsLusPossedes >= albumsPossedes) {
        statut = "Possédé et Lu";
      } else if (albumsLusPossedes > 0) {
        statut = "Possédé et Je lis";
      } else {
        statut = "Possédé et Non lu";
      }
    } else if (albumsNonPossedesLu > 0) {
      statut = "Non possédé mais Lu";
    } else {
      statut = "Non possédé et Non lu";
    }

    return {
      id_unique: serie.id_unique,
      titre: serie.titre,
      categorie: serie.categorie || "Autre",
      albums_possedes: albumsPossedes,
      albums_lus: albumsLusTotal,
      statut,
      albums_non_possedes_lu: albumsNonPossedesLu,
      albums_manquants: serie.albums_manquants || 0,
      nb_dedicace: serie.nb_dedicace || 0
    };
  });

return lignes.map(ligne => ({
  json: ligne
}));

// Get all series
const series = $input.all().map(item => item.json);

const stats = {
  "BD": {
    possedes: 0,
    possedes_lus: 0,
    non_possedes_lus: 0,
    dedicaces: 0,
    series_possedees: 0
  },
  "Comics": {
    possedes: 0,
    possedes_lus: 0,
    non_possedes_lus: 0,
    dedicaces: 0,
    series_possedees: 0
  },
  "Mangas": {
    possedes: 0,
    possedes_lus: 0,
    non_possedes_lus: 0,
    dedicaces: 0,
    series_possedees: 0
  },
  "Autre": {
    possedes: 0,
    possedes_lus: 0,
    non_possedes_lus: 0,
    dedicaces: 0,
    series_possedees: 0
  }
};

function toNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : 0;
}

const statutsPossession = [
  "Possédé et Lu",
  "Possédé et Non lu",
  "Possédé et Je lis",
  "Partiellement possédé"
];

// ======================================================
// MAIN CALCULATION
// ======================================================

for (const s of series) {
  const cat = s.categorie || "Autre";

  if (!stats[cat]) {
    stats[cat] = {
      possedes: 0,
      possedes_lus: 0,
      non_possedes_lus: 0,
      dedicaces: 0,
      series_possedees: 0
    };
  }

  const albumsPossedes = toNumber(s.albums_possedes);
  const albumsLus = toNumber(s.albums_lus);
  const albumsNonPossedesLu = toNumber(s.albums_non_possedes_lu);
  const nbDedicace = toNumber(s.nb_dedicace);

  // Existing calculations
  stats[cat].possedes += albumsPossedes;
  stats[cat].non_possedes_lus += albumsNonPossedesLu;
  stats[cat].dedicaces += nbDedicace;

  const lusEtPossedes = albumsLus - albumsNonPossedesLu;
  stats[cat].possedes_lus += Math.max(lusEtPossedes, 0);

  // Number of owned series
  if (statutsPossession.includes(s.statut)) {
    stats[cat].series_possedees++;
  }
}

// ======================================================
// GOOGLE SHEETS OUTPUT
// ======================================================

const ligneGoogleSheet = {};

for (const cat of ["BD", "Comics", "Mangas", "Autre"]) {
  const catStats = stats[cat];

  const hasData =
    catStats.possedes > 0 ||
    catStats.possedes_lus > 0 ||
    catStats.non_possedes_lus > 0 ||
    catStats.dedicaces > 0 ||
    catStats.series_possedees > 0;

  if (cat === "Autre" && !hasData) {
    continue;
  }

  ligneGoogleSheet[`${cat} - Possédés`] = catStats.possedes;
  ligneGoogleSheet[`${cat} - Possédés et Lus`] = catStats.possedes_lus;
  ligneGoogleSheet[`${cat} - Non possédés et Lus`] = catStats.non_possedes_lus;
  ligneGoogleSheet[`${cat} - Dédicaces`] = catStats.dedicaces;
  ligneGoogleSheet[`${cat} - Séries possédées`] = catStats.series_possedees;
}

return [
  {
    json: ligneGoogleSheet
  }
];

parameters.jsonBody:
={{
  {
    code: `
export default async function({ page, context }) {
  const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

  await page.setUserAgent(
    'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36'
  );

  function normalizeCookies(rawCookies) {
    if (!rawCookies) return [];

    if (Array.isArray(rawCookies)) return rawCookies;

    if (typeof rawCookies === 'string') {
      try {
        const parsed = JSON.parse(rawCookies);
        return Array.isArray(parsed) ? parsed : [];
      } catch (error) {
        return [];
      }
    }

    return [];
  }

  const cookies = normalizeCookies(context.cookies)
    .filter(cookie => cookie && cookie.name && typeof cookie.value !== 'undefined')
    .map(cookie => {
      const cleanCookie = { ...cookie };

      if (cleanCookie.sameSite === 'no_restriction') {
        cleanCookie.sameSite = 'None';
      }

      if (cleanCookie.sameSite === 'unspecified') {
        delete cleanCookie.sameSite;
      }

      delete cleanCookie.storeId;
      delete cleanCookie.hostOnly;
      delete cleanCookie.session;

      return cleanCookie;
    });

  if (cookies.length > 0) {
    await page.setCookie(...cookies);
  }

  async function openBasePage() {
    await page.goto(context.url, {
      waitUntil: 'domcontentloaded',
      timeout: 0
    });

    await sleep(10000);

    try {
      await page.waitForFunction(() => {
        const text = document.body ? document.body.innerText : '';

        return (
          text.includes('Ma collection') ||
          text.includes('Mes BD') ||
          text.includes('J\\'ai') ||
          text.includes('J\\'ai pas')
        );
      }, {
        timeout: 30000
      });
    } catch (error) {
      // Continue, session is checked after.
    }
  }

  async function checkSession() {
    return await page.evaluate(() => {
      const text = document.body ? document.body.innerText : '';

      const hasCollection =
        text.includes('Ma collection') ||
        text.includes('Mes BD') ||
        text.includes('J\\'ai') ||
        text.includes('J\\'ai pas');

      const hasLogin =
        text.includes('Connexion') ||
        text.includes('Se connecter') ||
        text.includes('Connectez-vous');

      return {
        hasCollection,
        hasLogin,
        preview: text.slice(0, 2000)
      };
    });
  }

  async function getCheckedStates() {
    return await page.evaluate(() => {
      function normalizeText(value) {
        return String(value || '')
          .replace(/[’´]/g, "'")
          .replace(/\\s+/g, ' ')
          .trim()
          .toLowerCase();
      }

      function isLabelCheckedByText(labelText) {
        const target = normalizeText(labelText);
        const labels = Array.from(document.querySelectorAll('label'));

        const label = labels.find(element => normalizeText(element.textContent) === target);

        if (!label) return null;

        const input = label.querySelector('input[type="checkbox"]');
        const hasCheckIcon = label.querySelector('svg') !== null;
        const hasSuccessClass =
          label.innerHTML.includes('border-success') ||
          label.innerHTML.includes('bg-success') ||
          label.innerHTML.includes('tw:text-success');

        return Boolean((input && input.checked) || hasCheckIcon || hasSuccessClass);
      }

      function isInputCheckedById(id) {
        const input = document.getElementById(id);

        if (!input) return null;

        const label = input.closest('label');
        const hasCheckIcon = label ? label.querySelector('svg') !== null : false;
        const hasSuccessClass = label
          ? (
              label.innerHTML.includes('border-success') ||
              label.innerHTML.includes('bg-success') ||
              label.innerHTML.includes('tw:text-success')
            )
          : false;

        return Boolean(input.checked || hasCheckIcon || hasSuccessClass);
      }

      return {
        checkBd: isInputCheckedById('checkBd'),
        checkComics: isInputCheckedById('checkComics'),
        checkMangas: isInputCheckedById('checkMangas'),
        lu: isLabelCheckedByText('Lu'),
        nonLu: isLabelCheckedByText('Non lu'),
        jai: isLabelCheckedByText("J'ai"),
        jaiPas: isLabelCheckedByText("J'ai pas"),
        prete: isLabelCheckedByText('Prêté'),
        dedicace: isLabelCheckedByText('Dédicacé'),
        editionOriginale: isLabelCheckedByText('Edition Originale')
      };
    });
  }

  async function setCheckboxById(id, desiredState) {
    const result = await page.evaluate((checkboxId, desired) => {
      const input = document.getElementById(checkboxId);

      if (!input) {
        return {
          found: false,
          changed: false,
          checkedBefore: null
        };
      }

      const label = input.closest('label');

      const hasCheckIcon = label ? label.querySelector('svg') !== null : false;
      const hasSuccessClass = label
        ? (
            label.innerHTML.includes('border-success') ||
            label.innerHTML.includes('bg-success') ||
            label.innerHTML.includes('tw:text-success')
          )
        : false;

      const checkedBefore = Boolean(input.checked || hasCheckIcon || hasSuccessClass);

      if (checkedBefore !== desired) {
        if (label) {
          label.scrollIntoView({ block: 'center' });
          label.click();
        } else {
          input.scrollIntoView({ block: 'center' });
          input.click();
        }

        return {
          found: true,
          changed: true,
          checkedBefore
        };
      }

      return {
        found: true,
        changed: false,
        checkedBefore
      };
    }, id, desiredState);

    await sleep(500);
    return result;
  }

  async function setCheckboxByText(text, desiredState) {
    const result = await page.evaluate((targetText, desired) => {
      function normalizeText(value) {
        return String(value || '')
          .replace(/[’´]/g, "'")
          .replace(/\\s+/g, ' ')
          .trim()
          .toLowerCase();
      }

      const target = normalizeText(targetText);
      const labels = Array.from(document.querySelectorAll('label'));

      const label = labels.find(element => normalizeText(element.textContent) === target);

      if (!label) {
        return {
          found: false,
          changed: false,
          checkedBefore: null
        };
      }

      const input = label.querySelector('input[type="checkbox"]');

      const hasCheckIcon = label.querySelector('svg') !== null;
      const hasSuccessClass =
        label.innerHTML.includes('border-success') ||
        label.innerHTML.includes('bg-success') ||
        label.innerHTML.includes('tw:text-success');

      const checkedBefore = Boolean((input && input.checked) || hasCheckIcon || hasSuccessClass);

      if (checkedBefore !== desired) {
        label.scrollIntoView({ block: 'center' });
        label.click();

        return {
          found: true,
          changed: true,
          checkedBefore
        };
      }

      return {
        found: true,
        changed: false,
        checkedBefore
      };
    }, text, desiredState);

    await sleep(500);
    return result;
