  "code": "export default async function({ page, context }) {
  const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

  // Configuration d'un User-Agent moderne pour éviter les blocages de sécurité
  await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36');

  // Nettoyage et normalisation stricte des cookies pour Puppeteer/Browserless
  const cookies = context.cookies.map(c => {
    const clean = { ...c };
    if (clean.sameSite === 'no_restriction') clean.sameSite = 'None';
    if (clean.sameSite === 'unspecified') delete clean.sameSite;
    delete clean.storeId;
    delete clean.hostOnly;
    delete clean.session;
    return clean;
  });
  await page.setCookie(...cookies);

  // Navigation directe vers l'URL de connexion fournie
  await page.goto(context.url, { waitUntil: 'networkidle2', timeout: 60000 });
  await sleep(3000);

  // Analyse avancée de l'état d'authentification
  const loginState = await page.evaluate(() => {
    const text = document.body ? document.body.innerText : '';
    const currentUrl = window.location.href;

    // Si les cookies sont valides, Bubble nous redirige hors de /login ou affiche l'interface membre
    const hasDisconnect = text.includes('Déconnexion') || text.includes('Mon compte') || text.includes('Mon profil');
    const isRedirected = !currentUrl.includes('/login');
    const hasLoginForm = text.includes('Se connecter') && (text.includes('Mot de passe') || text.includes('Identifiant'));

    return {
      connected: (hasDisconnect || isRedirected) && !hasLoginForm,
      currentUrl: currentUrl,
      preview: text.substring(0, 1000)
    };
  });

  return {
    url: loginState.currentUrl,
    titre: await page.title(),
    statut_session: loginState.connected ? 'valide' : 'invalide',
    debug: {
      url_depart: context.url,
      ...loginState
    }
  };
}",
