parameters.jsCode:
const input = $input.first()?.json || {};

let data = input;

// Browserless peut renvoyer soit directement l'objet,
// soit un objet avec data en string/object selon la config n8n.
if (typeof data === "string") {
  data = JSON.parse(data);
}

if (typeof data.data === "string") {
  data = JSON.parse(data.data);
} else if (data.data && typeof data.data === "object") {
  data = data.data;
}

if (data.error) {
  throw new Error(data.error);
}

const books = Array.isArray(data.books) ? data.books : [];

if (books.length === 0) {
  const debug = {
    statut_session: data.statut_session || null,
    library_count: data.library_count || 0,
    wishlist_count: data.wishlist_count || 0,
    debug: data.debug || null,
    keys_recues: Object.keys(data)
  };

  throw new Error(
    "Aucun livre Audible extrait. Debug: " +
    JSON.stringify(debug).slice(0, 4000)
  );
}

function cleanText(value, fallback = "") {
  return String(value || fallback)
    .replace(/\s+/g, " ")
    .trim();
}

const unique = new Map();

for (const book of books) {
  if (!book || !book.id_unique) continue;

  const cleanBook = {
    id_unique: cleanText(book.id_unique),
    titre: cleanText(book.titre, "Titre inconnu"),
    auteur: cleanText(book.auteur, "Auteur inconnu"),
    duree_brute: cleanText(book.duree_brute, "0 min"),
    statut: cleanText(book.statut, "Non classé"),
    genre: "Livre Audio"
  };

  const key = `${cleanBook.id_unique}-${cleanBook.statut}`;
  unique.set(key, cleanBook);
}

const result = Array.from(unique.values()).map(book => ({
  json: book
}));

if (result.length === 0) {
  const debug = {
    statut_session: data.statut_session || null,
    library_count: data.library_count || 0,
    wishlist_count: data.wishlist_count || 0,
    debug: data.debug || null,
    keys_recues: Object.keys(data)
  };

  throw new Error(
    "Aucun livre Audible valide après nettoyage. Debug: " +
    JSON.stringify(debug).slice(0, 4000)
  );
}

return result;

const books = $input.all();

let totalOwnedSeconds = 0;
let totalListenedSeconds = 0;

let countPossedesTotal = 0;
let countPossedesEcoutes = 0;
let countSouhaits = 0;

// Average only includes listened books with a valid duration.
let countEcoutesAvecDuree = 0;

// Min and max durations of listened audiobooks.
let maxListenedSeconds = -1;
let minListenedSeconds = Infinity;

let titreMaxEcoute = "Aucun";
let titreMinEcoute = "Aucun";

function normalizeText(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function parseDurationToSeconds(duration) {
  const text = normalizeText(duration)
    .replace(/heures?/g, "h")
    .replace(/hours?/g, "h")
    .replace(/minutes?/g, "min")
    .replace(/\s+et\s+/g, " ")
    .replace(/\s+and\s+/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  let hours = 0;
  let minutes = 0;

  const combinedMatch = text.match(/(\d{1,3})\s*h\s*(\d{1,2})\s*min/);
  const hourMatch = text.match(/(\d{1,3})\s*h/);
  const minuteMatch = text.match(/(\d{1,2})\s*min/);

  if (combinedMatch) {
    hours = parseInt(combinedMatch[1], 10);
    minutes = parseInt(combinedMatch[2], 10);
  } else {
    if (hourMatch) {
      hours = parseInt(hourMatch[1], 10);
    }

    if (minuteMatch) {
      minutes = parseInt(minuteMatch[1], 10);
    }
  }

  if (Number.isNaN(hours)) hours = 0;
  if (Number.isNaN(minutes)) minutes = 0;

  // Preserve the existing guard against incorrectly parsed durations.
  if (hours > 120 || minutes > 59) {
    return 0;
  }

  return (hours * 3600) + (minutes * 60);
}

function formatSecondsToDuration(seconds) {
  const safeSeconds = Number.isFinite(seconds) && seconds > 0 ? seconds : 0;

  const totalMinutes = Math.round(safeSeconds / 60);
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;

  return `${hours} h ${minutes} min`;
}

function normalizeStatus(status) {
  return normalizeText(status);
}

function getBookTitle(book) {
  return (
    book.titre ||
    book.title ||
    book.nom ||
    book.name ||
    "Titre inconnu"
  );
}

for (const item of books) {
  const book = item.json || {};

  const status = normalizeStatus(book.statut);
  const seconds = parseDurationToSeconds(book.duree_brute);
  const titre = getBookTitle(book);

  const isWishlist =
    status === "liste de souhait" ||
    status === "liste d envie" ||
    status === "liste d envies";

  const isOwned = status.startsWith("possede");

  const isListened =
    status === "possede et ecoute" ||
    status === "possede et ecoutee" ||
    status === "possede et lu" ||
    status === "possede et termine";

  if (isWishlist) {
    countSouhaits++;
    continue;
  }

  if (isOwned) {
    countPossedesTotal++;
    totalOwnedSeconds += seconds;
  }

  if (isListened) {
    countPossedesEcoutes++;
    totalListenedSeconds += seconds;

    if (seconds > 0) {
      countEcoutesAvecDuree++;

      if (seconds > maxListenedSeconds) {
        maxListenedSeconds = seconds;
        titreMaxEcoute = titre;
      }

      if (seconds < minListenedSeconds) {
        minListenedSeconds = seconds;
        titreMinEcoute = titre;
      }
    }
  }
}

const totalOwnedHours = Math.round(totalOwnedSeconds / 3600);
const totalListenedHours = Math.round(totalListenedSeconds / 3600);

const totalOwnedDurationFormatted =
  formatSecondsToDuration(totalOwnedSeconds);

const totalListenedDurationFormatted =
  formatSecondsToDuration(totalListenedSeconds);

const averageListenedSeconds =
  countEcoutesAvecDuree > 0
    ? totalListenedSeconds / countEcoutesAvecDuree
    : 0;

const averageListenedDurationFormatted =
  formatSecondsToDuration(averageListenedSeconds);

const maxEcouteFormatted =
  maxListenedSeconds > 0
    ? `${titreMaxEcoute} (${formatSecondsToDuration(maxListenedSeconds)})`
    : "Aucun";

const minEcouteFormatted =
  minListenedSeconds !== Infinity
    ? `${titreMinEcoute} (${formatSecondsToDuration(minListenedSeconds)})`
    : "Aucun";

const prixEstime = (countPossedesTotal * 9.95).toLocaleString("fr-FR", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2
});

return [
  {
    json: {
      Genre: "Livre Audio",

      "En possession (Total)": countPossedesTotal,
      "En possession et Lu": countPossedesEcoutes,
      "Liste de souhait": countSouhaits,

      // The existing Pages column stores total owned hours.
      "Pages": totalOwnedHours,

      // Overall durations.
      "Durée totale": totalOwnedDurationFormatted,
      "Heures écoutées": totalListenedHours,

      // Listened duration in seconds.
      "Durée écoutée": Math.round(totalListenedSeconds),

      // Human-readable listened duration.
      "Durée écoutée formatée": totalListenedDurationFormatted,

      // Estimated price with French formatting.
      "Prix": prixEstime,

      // Min, max and average durations of listened audiobooks.
      "Max": maxEcouteFormatted,
      "Min": minEcouteFormatted,
      "Moyenne Audio": averageListenedDurationFormatted,

      // Keep compatibility with the existing Google Sheets column.
      "Moyenne Roman": averageListenedDurationFormatted,

      "Max secondes": maxListenedSeconds > 0 ? maxListenedSeconds : 0,
      "Min secondes": minListenedSeconds !== Infinity ? minListenedSeconds : 0,
      "Moyenne secondes": Math.round(averageListenedSeconds)
    }
  }
];

