// Insert row1: Map Automatically.
//
// episodes_seen_count includes distinct watched specials.
// episodes_remaining_count counts remaining aired regular episodes.
// Rewatches never increase the number of distinct episodes seen.

function readSource(nodeName) {
  const entries = [];

  function visit(value) {
    if (value === null || value === undefined) return;

    if (typeof value === 'string') {
      if (value.trim()) visit(JSON.parse(value));
      return;
    }

    if (Array.isArray(value)) {
      for (const entry of value) visit(entry);
      return;
    }

    if (typeof value !== 'object') {
      throw new Error(`${nodeName}: invalid JSON response.`);
    }

    if (Object.keys(value).length === 0) return;

    if (value.error || Number(value.statusCode) >= 400) {
      throw new Error(`${nodeName}: API error.`);
    }

    if (value.movie || value.show) {
      entries.push(value);
      return;
    }

    for (const key of ['body', 'data', 'items', 'results']) {
      if (Object.prototype.hasOwnProperty.call(value, key)) {
        visit(value[key]);
        return;
      }
    }

    throw new Error(`${nodeName}: unrecognized response format.`);
  }

  for (const item of $(nodeName).all()) {
    visit(item.json);
  }

  return entries;
}

function mediaKey(media, kind) {
  const ids = media.ids || {};

  for (const provider of ['trakt', 'imdb', 'tmdb', 'tvdb', 'slug']) {
    const value = ids[provider];

    if (
      value !== null &&
      value !== undefined &&
      String(value).trim()
    ) {
      return `${provider}:${kind}:${String(value).trim()}`;
    }
  }

  if (ids.plex?.guid) {
    return `plex:${kind}:${ids.plex.guid}`;
  }

  throw new Error(
    `Missing ${kind} identifier: ${media.title || 'unknown'}.`
  );
}

function nonNegativeNumber(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const number = Number(value);

  return Number.isFinite(number) && number >= 0
    ? number
    : null;
}

const shows = new Map();
const runTime = Date.now();

function integerOrNull(value) {
  const number = nonNegativeNumber(value);

  return number !== null && Number.isInteger(number)
    ? number
    : null;
}

function getShow(show) {
  if (!show || typeof show !== 'object') {
    throw new Error('Missing show in a Trakt entry.');
  }

  const key = mediaKey(show, 'show');
  const updatedAt = Date.parse(show.updated_at) || 0;
  const airedEpisodes = integerOrNull(show.aired_episodes);
  const title = show.title || show.original_title || null;

  if (!shows.has(key)) {
    shows.set(key, {
      key,
      title,
      updatedAt,
      airedEpisodes,
      seenEpisodes: new Set(),
      seenAiredRegularEpisodes: new Set(),
      lastEpisodeTitle: null,
      lastWatchedAt: -Infinity,
      hasHistory: false,
    });
  }

  const current = shows.get(key);

  if (updatedAt >= current.updatedAt) {
    current.title = title || current.title;
    current.airedEpisodes = airedEpisodes ?? current.airedEpisodes;
    current.updatedAt = updatedAt;
  } else {
    current.title = current.title || title;
    current.airedEpisodes = current.airedEpisodes ?? airedEpisodes;
  }

  return current;
}

function episodeKey(episode) {
  const season = integerOrNull(episode.season);
  const number = integerOrNull(episode.number);

  // Season/episode coordinates are unique within one show.
  if (season !== null && number !== null) {
    return `season:${season}:episode:${number}`;
  }

  const ids = episode.ids || {};

  for (const provider of ['trakt', 'imdb', 'tmdb', 'tvdb']) {
    const value = ids[provider];

    if (
      value !== null &&
      value !== undefined &&
      String(value).trim()
    ) {
      return `${provider}:${String(value).trim()}`;
    }
  }

  throw new Error('Missing identifier for a watched episode.');
}

// Include all watchlisted shows, even when none of their episodes were seen.
for (const entry of readSource('Trakt API - Get Stats1')) {
  if (entry.show) {
    getShow(entry.show);
  }
}

// Process the complete paginated episode history.
for (const entry of readSource('Trakt API - Get Stats3')) {
  if (!entry.episode || typeof entry.episode !== 'object') {
    throw new Error('Missing episode in a Trakt history entry.');
  }

  const current = getShow(entry.show);
  const episode = entry.episode;
  const key = episodeKey(episode);

  current.seenEpisodes.add(key);

  const season = integerOrNull(episode.season);

  const firstAired = Date.parse(
    episode.first_aired ||
    episode.effective_release_date ||
    episode.released ||
    ''
  );

  // Match the aired_episodes total:
  // exclude season 0 and episodes with a known future release date.
  if (
    season !== null &&
    season > 0 &&
    (
      !Number.isFinite(firstAired) ||
      firstAired <= runTime
    )
  ) {
    current.seenAiredRegularEpisodes.add(key);
  }

  const parsedDate = Date.parse(entry.watched_at);

  const watchedAt = Number.isFinite(parsedDate)
    ? parsedDate
    : -Infinity;

  // Keep the latest viewing event, including rewatches.
  if (!current.hasHistory || watchedAt > current.lastWatchedAt) {
    current.lastEpisodeTitle = episode.title || null;
    current.lastWatchedAt = watchedAt;
  }

  current.hasHistory = true;
}

return [...shows.values()]
  .sort((a, b) =>
    a.key.localeCompare(b.key, 'en', { numeric: true })
  )
  .map(show => {
    // Unknown totals stay null instead of incorrectly indicating completion.
    const remaining = show.airedEpisodes === null
      ? null
      : Math.max(
          0,
          show.airedEpisodes - show.seenAiredRegularEpisodes.size
        );

    const viewingStatus = !show.hasHistory
      ? 'Watchlist'
      : remaining === 0
        ? 'À jour'
        : 'En cours de visionnage';

    return {
      json: {
        series_uuid: show.key,
        series_name: show.title || show.key,
        episodes_seen_count: show.seenEpisodes.size,
        last_episode_title: show.lastEpisodeTitle,
        episodes_remaining_count: remaining,
        Statut: viewingStatus,
      },
    };
  });

