const input = $input.first().json;
const result = input.data ?? input;

if (
  input.error ||
  result.statut_session !== 'valide'
) {
  throw new Error(
    result.erreur ||
    'Loadia statistics request failed.'
  );
}

const raw = result.donnees;

if (
  !Array.isArray(raw?.tiles) ||
  !Array.isArray(raw?.ratings)
) {
  throw new Error('Missing Loadia statistics data.');
}

if (
  !Object.prototype.hasOwnProperty.call(raw, 'advanced')
) {
  throw new Error(
    'Update Stat and run it again to extract the advanced statistics.'
  );
}

const clean = (value) =>
  String(value ?? '').replace(/\s+/g, ' ').trim();

function parseNumber(value, nullable = false) {
  const text = clean(value)
    .replace(/\s/g, '')
    .replace(',', '.');

  if (
    nullable &&
    ['—', '–', '-', ''].includes(text)
  ) {
    return null;
  }

  if (!/^\d+(?:\.\d+)?$/.test(text)) {
    throw new Error('Invalid number: ' + clean(value));
  }

  const parsed = Number(text);

  if (!Number.isFinite(parsed)) {
    throw new Error('Invalid number: ' + clean(value));
  }

  return parsed;
}

function parseCount(value, nullable = false) {
  const number = parseNumber(value, nullable);

  if (
    number !== null &&
    !Number.isSafeInteger(number)
  ) {
    throw new Error('Invalid count: ' + clean(value));
  }

  return number;
}

function parseRating(value) {
  const number = parseNumber(value, true);

  if (
    number !== null &&
    (number < 0 || number > 5)
  ) {
    throw new Error('Invalid rating: ' + clean(value));
  }

  return number;
}

function parseEntries(value) {
  return parseCount(
    clean(value).replace(/\s*entrées?$/iu, '')
  );
}

function formatPlatforms(value) {
  const text = clean(value);

  if (!text) return null;

  if (['—', '–', '-'].includes(text)) {
    return text;
  }

  return text
    .split(/\s*\|\s*/)
    .map((part) => {
      const match = part.match(
        /^(.+)\s*:\s*(\d[\d\s]*)$/u
      );

      if (!match) {
        throw new Error(
          'Missing platform separators. Update Stat and run Stat again before Stat1.'
        );
      }

      return (
        clean(match[1]) +
        ' : ' +
        parseCount(match[2])
      );
    })
    .join(' | ');
}

function indexRows(rows) {
  if (!Array.isArray(rows)) {
    throw new Error('Missing statistics rows.');
  }

  const seen = new Set();

  return Object.fromEntries(
    rows.map((row) => {
      const label = clean(row.label);

      if (!label || seen.has(label)) {
        throw new Error(
          'Invalid or duplicate statistic label.'
        );
      }

      seen.add(label);

      return [label, row.value];
    })
  );
}

function parseBreakdown(rows, parser = parseCount) {
  return Object.fromEntries(
    Object.entries(indexRows(rows)).map(
      ([label, value]) => [label, parser(value)]
    )
  );
}

function splitRecord(value) {
  const text = clean(value);

  if (['—', '–', '-', ''].includes(text)) {
    return null;
  }

  const position = text.lastIndexOf('·');

  if (
    position <= 0 ||
    position === text.length - 1
  ) {
    throw new Error(
      'Invalid activity record: ' + text
    );
  }

  return [
    text.slice(0, position).trim(),
    text.slice(position + 1).trim()
  ];
}

function parseActivity(value, labelKey) {
  const parts = splitRecord(value);

  return parts
    ? {
        [labelKey]: parts[0],
        entrees: parseEntries(parts[1])
      }
    : null;
}

const tiles = Object.fromEntries(
  raw.tiles.map((tile) => [
    clean(tile.label),
    tile.value
  ])
);

const fields = {
  total_collection: 'Collection',
  termines: 'Terminés',
  en_cours: 'En cours',
  envies: 'Envies',
  a_jouer: 'À jouer',
  abandonnes: 'Abandonnés',
  critiques: 'Critiques',
  coups_de_coeur: 'Coups de cœur',
  completes_100_pourcent: '100 %',
  jeux_notes: 'Notés'
};

const stats = {};

for (const [key, label] of Object.entries(fields)) {
  if (!(label in tiles)) {
    throw new Error('Missing statistic: ' + label);
  }

  const value = parseNumber(tiles[label]);

  if (!Number.isSafeInteger(value)) {
    throw new Error('Invalid count: ' + label);
  }

  stats[key] = value;
}

if (!('Heures réelles' in tiles)) {
  throw new Error('Missing playtime statistic.');
}

if (!('Note moyenne' in tiles)) {
  throw new Error('Missing average rating.');
}

stats.heures_reelles = parseNumber(
  tiles['Heures réelles']
);

stats.note_moyenne = parseNumber(
  tiles['Note moyenne'],
  true
);

const ratings = {};

for (const row of raw.ratings) {
  const rating = parseNumber(row.label);
  const count = parseNumber(row.value);

  if (
    rating < 0.5 ||
    rating > 5 ||
    !Number.isInteger(rating * 2) ||
    !Number.isSafeInteger(count) ||
    Object.prototype.hasOwnProperty.call(
      ratings,
      String(rating)
    )
  ) {
    throw new Error('Invalid rating distribution.');
  }

  ratings[String(rating)] = count;
}

if (
  Object.keys(ratings).length !== 10 ||
  Object.values(ratings).reduce(
    (sum, value) => sum + value,
    0
  ) !== stats.jeux_notes
) {
  throw new Error(
    'Rating counts do not match the statistics.'
  );
}

const advancedStats = {};

if (raw.advanced !== null) {
  const advanced = raw.advanced;
  const records = indexRows(advanced.records);

  const record = (label) => {
    if (
      !Object.prototype.hasOwnProperty.call(
        records,
        label
      )
    ) {
      throw new Error(
        'Missing advanced statistic: ' + label
      );
    }

    return records[label];
  };

  const completion = parseNumber(
    clean(record('Taux de complétion'))
      .replace(/\s*%$/, ''),
    true
  );

  if (
    completion !== null &&
    completion > 100
  ) {
    throw new Error(
      'Invalid completion percentage.'
    );
  }

  const bestGame = splitRecord(
    record('Jeu le mieux noté')
  );

  if (!Array.isArray(advanced.years)) {
    throw new Error('Missing annual statistics.');
  }

  const years = new Set();

  Object.assign(advancedStats, {
    mois_le_plus_actif: parseActivity(
      record('Mois le plus actif'),
      'mois'
    ),

    plus_longue_serie_jours: parseCount(
      clean(record('Plus longue série'))
        .replace(/\s*jours?$/iu, ''),
      true
    ),

    taux_completion_pourcent: completion,

    notes_parfaites: parseCount(
      record('Notes parfaites')
    ),

    jeu_le_mieux_note: bestGame
      ? {
          titre: bestGame[0],
          note: parseRating(bestGame[1])
        }
      : null,

    jour_le_plus_actif: parseActivity(
      record('Jour le plus actif'),
      'jour'
    ),

    statistiques_par_annee: advanced.years.map(
      (row) => {
        const year = parseCount(row.year);

        if (years.has(year)) {
          throw new Error(
            'Duplicate year in annual statistics.'
          );
        }

        years.add(year);

        return {
          annee: year,
          entrees: parseEntries(row.entries),
          note: parseRating(row.rating)
        };
      }
    )
  });
}

const playedGames =
  stats.termines +
  stats.en_cours +
  stats.abandonnes;

const backlogGames = stats.a_jouer;

const libraryTotal = playedGames + backlogGames;

return [
  {
    json: {
      type: 'statistiques',
      source: 'Loadia',
      date_extraction: result.date_extraction,

      total_collection: stats.total_collection,
      jeux_joues: playedGames,
