const input = $input.first().json;
const result = input.data ?? input;

if (input.error || result.statut_session !== 'valide') {
  throw new Error(
    result.erreur || 'Loadia library request failed.'
  );
}

const raw = result.donnees;

if (!Array.isArray(raw?.games) || !raw.counts) {
  throw new Error('Missing library data.');
}

const clean = (value) =>
  String(value ?? '').replace(/\s+/g, ' ').trim();

function parseCount(value) {
  const text = clean(value).replace(/\s/g, '');

  if (!/^\d+$/.test(text)) {
    throw new Error('Invalid library count.');
  }

  const count = Number(text);

  if (!Number.isSafeInteger(count)) {
    throw new Error('Invalid library count.');
  }

  return count;
}

function parseRating(value) {
  if (value === null) return null;

  const match = clean(value).match(
    /(?:^|:\s*)(\d+(?:[.,]\d+)?)\s*\/\s*(\d+(?:[.,]\d+)?)$/
  );

  if (!match) {
    throw new Error('Invalid game rating: ' + clean(value));
  }

  const rating = Number(match[1].replace(',', '.'));
  const maximum = Number(match[2].replace(',', '.'));

  if (
    maximum !== 5 ||
    rating < 0 ||
    rating > 5 ||
    !Number.isInteger(rating * 2)
  ) {
    throw new Error('Unexpected game rating scale.');
  }

  return rating;
}

const statusLabels = {
  backlog: 'Envie',
  owned: 'À jouer',
  played: 'Terminé',
  playing: 'En cours',
  abandoned: 'Abandonné'
};

const byId = new Map();

for (const game of raw.games) {
  const id = clean(game.id);

  if (!id || !clean(game.titre)) {
    throw new Error('A game has no identifier or title.');
  }

  if (!Object.prototype.hasOwnProperty.call(statusLabels, game.statut)) {
    throw new Error('Unknown game status for: ' + id);
  }

  if (
    !Object.prototype.hasOwnProperty.call(game, 'note_texte') ||
    typeof game.coup_de_coeur !== 'boolean' ||
    typeof game.complete_100_pourcent !== 'boolean' ||
    !Array.isArray(game.marques)
  ) {
    throw new Error(
      'Missing game metadata. Run the updated library node first.'
    );
  }

  const previous = byId.get(id);

  if (
    previous &&
    JSON.stringify(previous) !== JSON.stringify(game)
  ) {
    throw new Error('Conflicting data for game: ' + id);
  }

  byId.set(id, game);
}

const games = [...byId.values()];
const expected = parseCount(raw.counts.Tout);

if (games.length !== expected) {
  throw new Error(
    'Incomplete library: expected ' +
    expected +
    ', got ' +
    games.length
  );
}

for (const [status, label] of Object.entries(statusLabels)) {
  if (!(label in raw.counts)) {
    throw new Error('Missing library counter: ' + label);
  }

  const actual = games.filter(
    (game) => game.statut === status
  ).length;

  if (parseCount(raw.counts[label]) !== actual) {
    throw new Error('Library count mismatch for: ' + label);
  }
}

if (
  !result.date_extraction ||
  !Number.isFinite(Date.parse(result.date_extraction))
) {
  throw new Error('Missing or invalid extraction date.');
}

return games.map((game) => ({
  json: {
    source: 'Loadia',
    id_jeu: clean(game.id),
    titre: clean(game.titre),

    statut: statusLabels[game.statut],
    statut_loadia: game.statut,

    dans_ludotheque: game.statut !== 'backlog',
    liste_souhait: game.statut === 'backlog',

    note: parseRating(game.note_texte),
    coup_de_coeur: game.coup_de_coeur,
    complete_100_pourcent: game.complete_100_pourcent,

    url: game.url,
    image: game.image || null,

    marques: [
      ...new Set(game.marques.map(clean).filter(Boolean))
    ].join(' | '),

    date_extraction: result.date_extraction
  },

  pairedItem: {
    item: 0
  }
}));

