function unwrapResponse(value) {
  let current = value;
  for (let i = 0; i < 4; i++) {
    if (typeof current === "string") {
      try { current = JSON.parse(current); } catch { throw new Error("Réponse Browserless non JSON"); }
    } else if (current && typeof current === "object" && "data" in current && !("ok" in current)) {
      current = current.data;
    } else break;
  }
  if (!current || typeof current !== "object" || Array.isArray(current)) throw new Error("Réponse Browserless vide ou invalide");
  if (current.error || current.erreur || current.ok === false) throw new Error(String(current.error?.message || current.error || current.erreur || "Échec MyLudo"));
  return current;
}
try {
  const result = unwrapResponse($input.first().json);
  if (result.statut_session !== 'valide' || !Array.isArray(result.sections) || result.sections.length !== 2 || result.sections.some(s => !s.accessible)) throw new Error('Accès aux deux listes non confirmé');
  return [{ json: result }];
} catch (error) {
  return [{ json: { ok: false, statut_session: 'inaccessible', erreur: error.message } }];
}

