  return current;
}
const manifest = unwrapResponse($input.first().json);
if (manifest.profile !== $('Paramètres MyLudo').first().json.profile) throw new Error('Mauvais profil extrait');
if (!Array.isArray(manifest.sections) || manifest.sections.length !== 2 || !Array.isArray(manifest.rows)) throw new Error('Listes MyLudo manquantes');
for (const name of ['collection', 'wishlist']) {
  const section = manifest.sections.find(s => s.section === name);
  const rows = manifest.rows.filter(r => r.statuts === name);
  if (!section || !section.complete || !Number.isInteger(section.total) || section.total < 0 || rows.length !== section.total || section.count !== section.total) throw new Error('Liste incomplète : ' + name);
}
if (manifest.rows.length !== manifest.sections.reduce((sum,s) => sum+s.total, 0)) throw new Error('Comptage global incohérent');
const keys = new Set();
const uniqueGames = new Map();
for (const row of manifest.rows) {
  const key = row.statuts + ':' + row.id;
  if (!row.Nom || !row.id || keys.has(key)) throw new Error('Jeu manquant ou répété : ' + key);
  keys.add(key);
  uniqueGames.set(row.id, { id: row.id, url: row.url });
}
const games = [...uniqueGames.values()];
const size = Math.max(1, Math.min(3, Number($('Paramètres MyLudo').first().json.batch_size) || 3));
const batches = [];
for (let i=0; i<games.length; i+=size) batches.push({ json: { batch: batches.length, games: games.slice(i,i+size) } });
// Keep one empty batch so an explicitly empty profile can still be validated.
return batches.length ? batches : [{ json: { batch: 0, games: [] } }];

