async function prepareBrowser(page, rawContext) {
  const context = typeof rawContext === "string" ? JSON.parse(rawContext) : (rawContext ?? {});
  const profile = context.profile ?? "ludomaster-139495";
  const profileId = profile.match(/-(\d+)$/)?.[1];
  if (!profileId || !/^[a-z0-9-]+$/i.test(profile)) throw new Error("Profil MyLudo invalide");
  page.setDefaultNavigationTimeout(20000);
  page.setDefaultTimeout(18000);
  await page.setViewport({ width: 1365, height: 1000 });
  await page.setRequestInterception(true);
  page.on("request", request => {
    const action = ["image", "font", "media"].includes(request.resourceType()) ? request.abort() : request.continue();
    action.catch(() => {});
  });
  if (Array.isArray(context.cookies) && context.cookies.length) {
    const cookies = context.cookies.map(cookie => {
      const domain = String(cookie.domain ?? "www.myludo.fr").replace(/^\./, "");
      if (domain !== "myludo.fr" && !domain.endsWith(".myludo.fr")) throw new Error("Cookie hors du domaine MyLudo");
      return { ...cookie, domain: cookie.domain ?? ".myludo.fr", path: cookie.path ?? "/" };
    });
    await page.setCookie(...cookies);
  }
  return { ...context, profile, profileId };
}

export default async function scrapeDetails({ page, context = {} }) {
  const config = await prepareBrowser(page, context);
  if (!Array.isArray(config.games) || config.games.length > 3) throw new Error("Lot de fiches invalide (3 maximum)");
  const details = [];
  for (const game of config.games) {
    if (!/^\d+$/.test(String(game.id)) || !new RegExp("^https://www\\.myludo\\.fr/#!/game/[^/?#]+-" + game.id + "$", "i").test(game.url)) {
      throw new Error("Lien de fiche invalide pour " + game.id);
    }
    await page.goto("about:blank");
    const response = await page.goto(game.url, { waitUntil: "domcontentloaded" });
    if (response && response.status() >= 400) throw new Error(game.id + " : HTTP " + response.status());
    await page.waitForFunction(id => {
      const infoHref = document.querySelector('main .tabs a[data-target="info"][href]')?.getAttribute("href") ?? "";
      const actual = infoHref.match(/-(\d+)\/info(?:$|[?#])/)?.[1] ?? document.querySelector('main .open-breakdown[data-context="game"][data-id]')?.getAttribute("data-id");
      return actual === String(id) && !!document.querySelector("main .cover-title") && !!document.querySelector("main #info .card-content.details");
    }, { timeout: 18000 }, game.id);
    const detail = await page.evaluate(readGameDetails, game.id);
    if (!detail.ready) throw new Error("Fiche incomplète ou mauvaise édition : " + game.id);
    details.push(detail);
    await new Promise(resolve => setTimeout(resolve, 350));
  }
  return { data: { ok: true, batch: config.batch, details }, type: "application/json" };
}

