    copy.querySelectorAll("i").forEach(n => n.remove());

    return clean(copy.textContent);
  };

  const root = document.querySelector("main #" + section);

  const profile = document.querySelector(
    "main .profil-header .btn-share[data-url]"
  );

  const profileUrl =
    profile?.getAttribute("data-url") ?? "";

  if (!root) {
    return {
      section,
      profileUrl,
      ready: false,
      rows: [],
      displayed: null,
      total: null
    };
  }

  const visible =
    root.getClientRects().length > 0 &&
    getComputedStyle(root).display !== "none";

  const counterText =
    text(
      root.querySelector(
        ".filters > .chip"
      )
    );

  const counter =
    counterText
      .replace(/\\s/g, "")
      .match(/^(\\d+)(?:\\/(\\d+))?$/);

  const displayed =
    counter
      ? Number(counter[1])
      : null;

  const total =
    counter
      ? Number(
          counter[2] ??
          counter[1]
        )
      : null;

  const rows = [
    ...root.querySelectorAll(
      ".game"
    )
  ].map(card => {
    const link =
      card.querySelector(
        '.title a[href*="#!/game/"]'
      ) ||
      card.querySelector(
        '.picture a[href*="#!/game/"]'
      );

    if (!link) {
      throw new Error(
        "Carte sans lien MyLudo dans " +
        section
      );
    }

    const href =
      link.getAttribute(
        "href"
      );

    const id =
      href.match(
        /-(\\d+)(?:\\/|$)/
      )?.[1];

    if (!id) {
      throw new Error(
        "Identifiant de jeu introuvable : " +
        href
      );
    }

    const title =
      text(link) ||
      clean(
        link.getAttribute(
          "title"
        )
      );

    const subtitle =
      text(
        card.querySelector(
          ".subtitle"
        )
      );

    const label =
      text(
        card.querySelector(
          ".status"
        )
      );

    if (!title) {
      throw new Error(
        "Nom de jeu manquant : " +
        id
      );
    }

    return {
      id,

      url:
        "https://www.myludo.fr/" +
        href,

      Nom:
        subtitle &&
        !title
          .toLowerCase()
          .includes(
            subtitle.toLowerCase()
          )
          ? title +
            " - " +
            subtitle
          : title,

      statuts:
        section,

      edition_label:
        label,

      price_label:
        section ===
          "wishlist"
          ? text(
              card.querySelector(
                "p.context"
              )
            )
          : null
    };
  });

  const filters =
    root.querySelector(
      "#filter-panel"
    );

  const words =
    filters
      ?.querySelector(
        'input[name="words"]'
      )
      ?.value ?? "";

  const groups =
    filters
      ? [
          ...filters.querySelectorAll(
            ".btn-group[data-name]"
          )
        ].map(g => ({
          name:
            g.getAttribute(
              "data-name"
            ),

          value:
            g.getAttribute(
              "data-value"
            ) ?? ""
        }))
      : [];

  return {
    section,
    profileUrl,

    ready:
      visible &&
      counter !== null,

    displayed,
    total,
    counterText,
    rows,

    hasFull:
      !!root.querySelector(
        "a.full"
      ),

    hasMore:
      !!root.querySelector(
        "a.more"
      ),

    words,

    filterGroups:
      groups
  };
}


// ============================================================
// BROWSER
// ============================================================

async function prepareBrowser(
  page,
  rawContext
) {
  const context =
    typeof rawContext ===
    "string"
      ? JSON.parse(
          rawContext
        )
      : (
          rawContext ??
          {}
        );

  const profile =
    context.profile ??
    "ludomaster-139495";

  const profileId =
    profile.match(
      /-(\\d+)$/
    )?.[1];

  if (
    !profileId ||
    !/^[a-z0-9-]+$/i.test(
      profile
    )
  ) {
    throw new Error(
      "Profil MyLudo invalide"
    );
  }

  page.setDefaultNavigationTimeout(
    20000
  );

  page.setDefaultTimeout(
    18000
  );

  await page.setViewport({
    width: 1365,
    height: 1000
  });

  await page.setRequestInterception(
    true
  );

  page.on(
    "request",
    request => {
      const action =
        [
          "image",
          "font",
          "media"
        ].includes(
          request.resourceType()
        )
          ? request.abort()
          : request.continue();

      action.catch(
        () => {}
      );
    }
  );

  if (
    Array.isArray(
      context.cookies
    ) &&
    context.cookies.length
  ) {
    const cookies =
      context.cookies.map(
        cookie => {
          const domain =
            String(
              cookie.domain ??
              "www.myludo.fr"
            ).replace(
              /^\\./,
              ""
            );

          if (
            domain !==
              "myludo.fr" &&
            !domain.endsWith(
              ".myludo.fr"
            )
          ) {
            throw new Error(
              "Cookie hors du domaine MyLudo"
            );
          }

          return {
            ...cookie,

            domain:
              cookie.domain ??
              ".myludo.fr",

            path:
              cookie.path ??
              "/"
          };
        }
      );

    await page.setCookie(
      ...cookies
    );
  }

  return {
    ...context,
    profile,
    profileId
  };
}


// ============================================================
// OPEN SECTION
// ============================================================

async function openProfileSection(
  page,
  config,
  section,
  resetFilters
) {
  await page.goto(
    "about:blank"
  );

  const response =
    await page.goto(
      "https://www.myludo.fr/#!/profil/" +
        config.profile +
        "/" +
        section,

      {
        waitUntil:
          "domcontentloaded"
      }
    );

  if (
    response &&
    response.status() >=
      400
  ) {
    throw new Error(
      section +
      " : HTTP " +
      response.status()
    );
  }

  try {
    await page.waitForFunction(
      ({
        section,
        profileId
      }) => {
        const share =
          document.querySelector(
            "main .profil-header .btn-share[data-url]"
          );

        return (
          share
            ?.getAttribute(
              "data-url"
            )
            ?.endsWith(
              "-" +
              profileId
            ) &&
          !!document.querySelector(
            'main .tabs a[href="#' +
              section +
              '"]'
          )
        );
      },

      {
        timeout: 18000
      },

      {
        section,
        profileId:
          config.profileId
      }
    );
  } catch {
    throw new Error(
      section +
      " : profil/onglet non chargé"
    );
  }

  await page.evaluate(
    section => {
      const tab =
        document.querySelector(
          'main .tabs a[href="#' +
            section +
            '"]'
        );

      const root =
        document.querySelector(
          "main #" +
          section
        );

      if (
        tab &&
        (
          !root ||
          !root
            .getClientRects()
            .length ||
          getComputedStyle(
            root
          ).display ===
            "none" ||
          !tab.classList.contains(
            "active"
          )
        )
      ) {
        tab.click();
      }
    },

    section
  );

  const waitReady =
    async label => {
      try {
        await page.waitForFunction(
          section => {
            const root =
              document.querySelector(
                "main #" +
                section
              );

            const chip =
              root
                ?.querySelector(
                  ".filters > .chip"
                )
                ?.cloneNode(
                  true
                );

            if (
              !root ||
              !chip ||
              !root
                .getClientRects()
                .length ||
              getComputedStyle(
                root
              ).display ===
                "none"
            ) {
              return false;
            }

            chip
              .querySelectorAll(
                "i"
              )
              .forEach(
                el =>
                  el.remove()
              );

            return /^\\d+(?:\\/\\d+)?$/.test(
              chip.textContent.replace(
                /\\s/g,
                ""
              )
            );
          },

          {
            timeout: 18000
          },

          section
        );
      } catch {
        throw new Error(
          section +
          " : compteur non prêt (" +
          label +
          ")"
        );
      }
    };

  await waitReady(
    "ouverture"
  );

  if (resetFilters) {
    await page.evaluate(
      section =>
        document
          .querySelector(
            "main #" +
            section +
            " .btn-clear-filters"
          )
          ?.click(),

      section
    );

    await new Promise(
      resolve =>
        setTimeout(
          resolve,
          700
        )
    );

    await waitReady(
      "après suppression des filtres"
    );
  }

  const state =
    await page.evaluate(
      readProfileSection,
      section
    );

  if (
    !state.ready ||
    !state.profileUrl.endsWith(
      "-" +
      config.profileId
    )
  ) {
    throw new Error(
      section +
      " : accès au profil non confirmé"
    );
  }

  return state;
}


// ============================================================
// LOAD ENTIRE SECTION
// ============================================================

async function loadEntireSection(
  page,
  config,
  section
) {
  let state =
    await openProfileSection(
      page,
      config,
      section,
      true
    );

  if (
    state.words ||
    state.filterGroups.some(
      g =>
        g.name ===
          "filter" &&
        g.value
    )
  ) {
    throw new Error(
      section +
      " : filtre encore actif"
    );
  }

  let clicks = 0;

  while (
    state.rows.length !==
    state.total
  ) {
    if (
      state.rows.length >
        state.total ||
      clicks >= 20
    ) {
      throw new Error(
        section +
        " : compteur incohérent ou pagination incomplète"
      );
    }

    const previousCount =
      state.rows.length;

    const clicked =
      await page.evaluate(
        section => {
          const root =
            document.querySelector(
              "main #" +
              section
            );

          const button =
            root
              ?.querySelector(
                "a.full"
              ) ||
            root
              ?.querySelector(
                "a.more"
              );

          if (!button) {
            return false;
          }

          button.click();

          return true;
        },

        section
      );

    if (!clicked) {
      throw new Error(
        section +
        " : bouton Tout/Plus absent, " +
        previousCount +
        "/" +
        state.total
      );
    }

    try {
      await page.waitForFunction(
        ({
          section,
          previousCount
        }) => {
          const root =
            document.querySelector(
              "main #" +
              section
            );

          return (
            root &&
            root.querySelectorAll(
              ".game"
            ).length >
              previousCount
          );
        },

        {
          timeout: 20000
        },

        {
          section,
          previousCount
        }
      );
    } catch {
      throw new Error(
        section +
        " : aucun nouveau jeu après clic Tout/Plus (" +
        previousCount +
        "/" +
        state.total +
        ")"
      );
    }

    state =
      await page.evaluate(
        readProfileSection,
        section
      );

    if (!state.ready) {
      throw new Error(
        section +
        " : liste disparue pendant le chargement"
      );
    }

    clicks++;
  }

  await new Promise(
    resolve =>
      setTimeout(
        resolve,
        500
      )
  );

  state =
    await page.evaluate(
      readProfileSection,
      section
    );

  if (
    !state.ready ||
    state.rows.length !==
      state.total ||
    state.displayed !==
      state.total
  ) {
    throw new Error(
      section +
      " : extraction partielle (" +
      state.rows.length +
      "/" +
      state.total +
      ")"
    );
  }

  const ids =
    new Set(
      state.rows.map(
        row => row.id
      )
    );

  if (
    ids.size !==
    state.rows.length
  ) {
    throw new Error(
      section +
      " : identifiants répétés dans la liste"
    );
  }

  return {
    section,

    total:
      state.total,

    count:
      state.rows.length,

    complete:
      true,

    rows:
      state.rows
  };
}


// ============================================================
// READ PUBLIC STATS DIRECTLY FROM HIDDEN #stats
// ============================================================

async function readPublicStats(
  page
) {
  return await page.evaluate(
    () => {
      const clean = value =>
        String(value ?? "")
          .replace(
            /\\s+/g,
            " "
          )
          .trim();

      const normalize = value =>
        clean(value)
          .normalize(
            "NFD"
          )
          .replace(
            /[\\u0300-\\u036f]/g,
            ""
          )
          .toLowerCase();

      const text = el => {
        if (!el) {
          return "";
        }

        const copy =
          el.cloneNode(
            true
          );

        copy
          .querySelectorAll(
            "i"
          )
          .forEach(
            n =>
              n.remove()
          );

        return clean(
          copy.textContent
        );
      };

      const toInteger =
        value => {
          const match =
            clean(value)
              .replace(
                /[\\s\\u00a0\\u202f]/g,
                ""
              )
              .match(
                /-?\\d+/
              );

          return match
            ? Number(
                match[0]
              )
            : null;
        };

      const root =
        document.querySelector(
          "main #stats"
        );

      if (!root) {
        return {
          ready:
            false,

          reason:
            "#stats absent",

          duration:
            null,

          parties:
            null,

          details:
            null,

          top10:
            []
        };
      }

      const cards = [
        ...root.querySelectorAll(
          ".card-content"
        )
      ];

      const findCard =
        heading =>
          cards.find(
            card =>
              normalize(
                text(
                  card.querySelector(
                    "h6"
                  )
                )
              ) ===
              normalize(
                heading
              )
          ) ?? null;

      const readStats =
        (
          card,
          selector
        ) => {
          const values = {};

          if (!card) {
            return values;
          }

          for (
            const container
            of card.querySelectorAll(
              ".stat-container"
            )
          ) {
            const label =
              normalize(
                text(
                  container.querySelector(
                    selector
                  )
                )
              );

            const value =
              toInteger(
                text(
                  container.querySelector(
                    ".stat-number"
                  )
                )
              );

            if (
              label &&
              value !== null
            ) {
              values[label] =
                value;
            }
          }

          return values;
        };


      // ========================================================
      // TOTAL PLAY TIME
      // ========================================================

      const durationValues =
        readStats(
          findCard(
            "Durée totale de jeu"
          ),
          ".stat-detail"
        );

      const duration = {
        years:
          durationValues.annees ??
          null,

        months:
          durationValues.mois ??
          null,

        days:
          durationValues.jours ??
          null,

        hours:
          durationValues.heures ??
          null,

        minutes:
          durationValues.minutes ??
          null
      };


      // ========================================================
      // PARTIES
      // ========================================================

      const partyValues =
        readStats(
          findCard(
            "Parties"
          ),
          ".stat-label"
        );

      const parties = {
        total:
          partyValues.total ??
          null,

        cooperation:
          partyValues.cooperation ??
          null,

        solo:
          partyValues.solo ??
          null
      };


      // ========================================================
      // DETAILS
      // ========================================================

      const detailValues =
        readStats(
          findCard(
            "Détails"
          ),
          ".stat-label"
        );

      const details = {
        games:
          detailValues.jeux ??
          null,

        places:
          detailValues.lieux ??
          null,

        h_index:
          detailValues[
            "h-index"
          ] ??
          null
      };


      // ========================================================
      // TOP 10
      // ========================================================

      const rankingTable = [
        ...root.querySelectorAll(
          "table.ranking-table"
        )
      ].find(
        table =>
          normalize(
            text(
              table.querySelector(
                "thead"
              )
            )
          ).includes(
            "top 10 jeu"
          )
      );

      const top10 =
        rankingTable
          ? [
              ...rankingTable
                .querySelectorAll(
                  "tbody tr"
                )
            ]
              .map(
                (
                  row,
                  index
                ) => {
                  const cells = [
                    ...row.querySelectorAll(
                      "td"
                    )
                  ];

                  const link =
                    cells[0]
                      ?.querySelector(
                        'a[href*="#!/game/"]'
                      );

                  if (!link) {
                    return null;
                  }

                  const href =
                    link.getAttribute(
                      "href"
                    ) ?? "";

                  const titleCopy =
                    link.cloneNode(
                      true
                    );

                  titleCopy
                    .querySelectorAll(
                      ".rank"
                    )
                    .forEach(
                      el =>
                        el.remove()
                    );

                  return {
                    rank:
                      toInteger(
                        text(
                          link.querySelector(
                            ".rank"
                          )
                        )
                      ) ??
                      index + 1,

                    id:
                      href.match(
                        /-(\\d+)\\/stats(?:$|[?#])/
                      )?.[1] ??
                      href.match(
                        /-(\\d+)(?:\\/|$)/
                      )?.[1] ??
                      null,

                    name:
                      text(
                        titleCopy
                      ),

                    duration_minutes:
                      toInteger(
                        text(
                          cells[1]
                        )
                      ) ??
                      0,

                    plays:
                      toInteger(
                        text(
                          cells[2]
                        )
                      ) ??
                      0,

                    url:
                      href.startsWith(
                        "http"
                      )
                        ? href
                        : "https://www.myludo.fr/" +
                          href
                  };
                }
              )
              .filter(
                Boolean
              )
          : [];

      const ready =
        Object
          .values(
            duration
          )
          .every(
            Number.isInteger
          ) &&
        Object
          .values(
            parties
          )
          .every(
            Number.isInteger
          ) &&
        Object
          .values(
            details
          )
          .every(
            Number.isInteger
          );

      return {
        ready,
        duration,
        parties,
        details,
        top10
      };
    }
  );
}


// ============================================================
// MAIN
// ============================================================

function optionalCount(value) {
  if (
    (typeof value !== "number" && typeof value !== "string") ||
    (typeof value === "string" && value.trim() === "")
  ) {
    return null;
  }

  const number = Number(value);
  return Number.isSafeInteger(number) && number >= 0 ? number : null;
}

function normalizePublicStats(value) {
  const isRecord = item =>
    item !== null && typeof item === "object" && !Array.isArray(item);
  const raw = isRecord(value) ? value : {};
  const readCounters = (group, keys) => Object.fromEntries(
    keys.map(key => [key, optionalCount(isRecord(group) ? group[key] : null)])
  );

  const duration = readCounters(raw.duration, [
    "years", "months", "days", "hours", "minutes"
  ]);
  const parties = readCounters(raw.parties, ["total", "cooperation", "solo"]);
  const details = readCounters(raw.details, ["games", "places", "h_index"]);
  const ready = raw.ready === true &&
    [duration, parties, details].every(group =>
      Object.values(group).every(number => number !== null)
    ) && Array.isArray(raw.top10);

  return {
    ...raw,
    ready,
    reason: ready ? null : String(raw.reason || "Statistiques absentes ou incomplètes"),
    duration,
    parties,
    details,
    top10: Array.isArray(raw.top10) ? raw.top10.filter(isRecord) : []
  };
}

function collectStatsWarnings(existing, publicStats) {
  const warnings = Array.isArray(existing) ? [...existing] : [];
  if (!publicStats.ready) {
    const warning = "Statistiques MyLudo indisponibles ou incomplètes : " + publicStats.reason;
    if (!warnings.includes(warning)) warnings.push(warning);
  }
  return warnings;
}

export default async function scrapeLists({
  page,
  context = {}
}) {
  const config =
    await prepareBrowser(
      page,
      context
    );

  // Keep the original working Collection logic.
  const collection =
    await loadEntireSection(
      page,
      config,
      "collection"
    );

  // Public statistics are optional; missing data must not stop the lists.
  let rawPublicStats;
  try {
    rawPublicStats = await readPublicStats(page);
  } catch (error) {
    rawPublicStats = {
      ready: false,
      reason: "Lecture des statistiques impossible : " + String(error?.message ?? error)
    };
  }

  const publicStats = normalizePublicStats(rawPublicStats);
  const warnings = collectStatsWarnings([], publicStats);

  // Keep the original working Wishlist logic.
  const wishlist =
    await loadEntireSection(
      page,
      config,
      "wishlist"
    );

  const sections = [
    collection,
    wishlist
  ];

  return {
    data: {
      ok: true,

      profile:
        config.profile,

      extracted_at:
        new Date()
          .toISOString(),

      sections,

      rows:
        sections.flatMap(
          section =>
            section.rows
        ),

      public_stats:
        publicStats,

      warnings
    },

    type:
      "application/json"
  };
}

