// ============================================================

function parseEuro(raw) {
  if (
    raw === null ||
    raw === undefined ||
    String(raw).trim() === ""
  ) {
    return null;
  }

  const text =
    String(raw).trim();

  // Explicitly free items have a known price of zero.
  if (/^gratuite?s?$/i.test(text)) {
    return 0;
  }

  // Missing prices remain unknown.
  if (
    /^(?:[-–—?]|n\/a|nc|n\.c\.|non renseign[eé]|indisponible)$/i.test(
      text
    )
  ) {
    return null;
  }

  const compact =
    text
      .replace(
        /[\s\u00a0\u202f]/g,
        ""
      )
      .replace(
        /(?:€|EUR)$/i,
        ""
      );

  const normalized =
    compact.includes(",")
      ? compact
          .replace(/\./g, "")
          .replace(",", ".")
      : compact;

  if (
    !/^\d+(?:\.\d{1,2})?$/.test(
      normalized
    )
  ) {
    throw new Error(
      "Prix illisible : " +
      text
    );
  }

  const amount =
    Number(normalized);

  if (
    !Number.isFinite(amount) ||
    amount < 0
  ) {
    throw new Error(
      "Prix invalide : " +
      text
    );
  }

  return amount;
}


// ============================================================
// EDITION / CATEGORY / YEAR
// ============================================================

function parseEdition(
  raw,
  fallbackDate = ""
) {
  const label =
    String(raw ?? "")
      .replace(/\s+/g, " ")
      .trim();

  const year =
    label.match(
      /\b[12]\d{3}\b/
    )?.[0] ||
    String(
      fallbackDate
    ).match(
      /\b[12]\d{3}\b/
    )?.[0];

  const type =
    label
      .replace(
        /\b[12]\d{3}\b/g,
        ""
      )
      .replace(
        /^[\s:–—-]+|[\s:–—-]+$/g,
        ""
      )
      .trim()
      .toLowerCase();

  const category =
    !type
      ? "jeu de base"

      : /\bstand[\s-]?alone\b/.test(
          type
        )
        ? "standalone"

        : /\bextension\b/.test(
            type
          )
          ? "extension"

          : /\baccessoire\b/.test(
              type
            )
            ? "accessoire"

            : /\bgoodie\b/.test(
                type
              )
              ? "goodie"

              : /\bd[eé]mo\b/.test(
                  type
                )
                ? "démo"

                : /\b(?:jeu de base|basegame)\b/.test(
                    type
                  )
                  ? "jeu de base"

                  : "autre";

  return {
    annee_sortie:
      year
        ? Number(year)
        : null,

    categorie:
      category,

    label,

    type,
  };
}


// ============================================================
// MANIFEST FROM ludothèque1
// ============================================================

const manifest =
  unwrapResponse(
    $('ludothèque1')
      .first()
      .json
  );


// ============================================================
// PUBLIC MYLUDO STATS
// ============================================================

function optionalCount(value) {
  if (
    (typeof value !== "number" && typeof value !== "string") ||
    (typeof value === "string" && value.trim() === "")
  ) {
    return null;
  }

  const number = Number(value);
  return Number.isSafeInteger(number) && number >= 0 ? number : null;
}

function normalizePublicStats(value) {
  const isRecord = item =>
    item !== null && typeof item === "object" && !Array.isArray(item);
  const raw = isRecord(value) ? value : {};
  const readCounters = (group, keys) => Object.fromEntries(
    keys.map(key => [key, optionalCount(isRecord(group) ? group[key] : null)])
  );

  const duration = readCounters(raw.duration, [
    "years", "months", "days", "hours", "minutes"
  ]);
  const parties = readCounters(raw.parties, ["total", "cooperation", "solo"]);
  const details = readCounters(raw.details, ["games", "places", "h_index"]);
  const ready = raw.ready === true &&
    [duration, parties, details].every(group =>
      Object.values(group).every(number => number !== null)
    ) && Array.isArray(raw.top10);

  return {
    ...raw,
    ready,
    reason: ready ? null : String(raw.reason || "Statistiques absentes ou incomplètes"),
    duration,
    parties,
    details,
    top10: Array.isArray(raw.top10) ? raw.top10.filter(isRecord) : []
  };
}

function collectStatsWarnings(existing, publicStats) {
  const warnings = Array.isArray(existing) ? [...existing] : [];
  if (!publicStats.ready) {
    const warning = "Statistiques MyLudo indisponibles ou incomplètes : " + publicStats.reason;
    if (!warnings.includes(warning)) warnings.push(warning);
  }
  return warnings;
}

const publicStats = normalizePublicStats(manifest.public_stats);
const warnings = collectStatsWarnings(manifest.warnings, publicStats);


// ============================================================
// DETAILS FROM GAME PAGES
// ============================================================

const detailsById =
  new Map();

for (
  const item
  of $input.all()
) {
  const batch =
    unwrapResponse(
      item.json
    );

  if (
    !Array.isArray(
      batch.details
    )
  ) {
    throw new Error(
      "Réponse de fiche invalide"
    );
  }

  for (
    const detail
    of batch.details
  ) {
    if (
      !detail.ready ||
      !detail.id ||
      detailsById.has(
        detail.id
      )
    ) {
      throw new Error(
        "Fiche manquante ou répétée : " +
        detail.id
      );
    }

    detailsById.set(
      detail.id,
      detail
    );
  }
}


// ============================================================
// VERIFY EVERY GAME HAS A DETAIL PAGE
// ============================================================

const expectedIds =
  new Set(
    manifest.rows.map(
      row => row.id
    )
  );

if (
  expectedIds.size !==
    detailsById.size ||

  [...expectedIds].some(
    id =>
      !detailsById.has(id)
  )
) {
  throw new Error(
    "Toutes les fiches n’ont pas été extraites : aucune modification de la table"
  );
}


// ============================================================
// BUILD FINAL DATA TABLE ROWS
// ============================================================

const rows =
  manifest.rows.map(
    card => {
      const detail =
        detailsById.get(
          card.id
        );

      const cardEdition =
        parseEdition(
          card.edition_label
        );

      const detailEdition =
        parseEdition(
          detail.edition_label,
          detail.release_label
        );

      // --------------------------------------------------------
      // YEAR CONSISTENCY
      // --------------------------------------------------------

      if (
        cardEdition.annee_sortie &&
        detailEdition.annee_sortie &&
        cardEdition.annee_sortie !==
          detailEdition.annee_sortie
      ) {
        throw new Error(
          "Année contradictoire pour " +
          card.Nom
        );
      }

      // --------------------------------------------------------
      // CATEGORY CONSISTENCY
      // --------------------------------------------------------

      if (
        cardEdition.label &&
        detailEdition.label &&
        cardEdition.categorie !==
          detailEdition.categorie
      ) {
        throw new Error(
          "Catégorie contradictoire pour " +
          card.Nom
        );
      }

      const year =
        cardEdition
          .annee_sortie ??
        detailEdition
          .annee_sortie;

      const category =
        cardEdition.label
          ? cardEdition.categorie

          : detailEdition.label
            ? detailEdition.categorie

            : "autre";

      // --------------------------------------------------------
      // GENRES
      // --------------------------------------------------------

      if (
        !Array.isArray(
          detail.genre
        )
      ) {
        throw new Error(
          "Genres non lus pour " +
          card.Nom
        );
      }

      // --------------------------------------------------------
      // PRICE
      // --------------------------------------------------------

      const price =
        parseEuro(
          card.statuts ===
            "wishlist"
            ? card.price_label
            : detail.price_label
        );

      return {
        Nom:
          card.Nom,

        statuts:
          card.statuts,

        genre:
          [
            ...new Set(
              detail.genre
                .map(
                  genre =>
                    String(
                      genre
                    ).trim()
                )
                .filter(
                  Boolean
                )
            )
          ].join(" | ") ||
          null,

        categorie:
          category,

        prix:
          price,

        annee_sortie:
          year,
      };
    }
  );


// ============================================================
// VERIFY COLLECTION / WISHLIST COUNTS
// ============================================================

for (
  const section
  of manifest.sections
) {
  const count =
    rows.filter(
      row =>
        row.statuts ===
        section.section
    ).length;

  if (
    !section.complete ||
    count !==
      section.total
  ) {
    throw new Error(
      "Comptage final incomplet : " +
      section.section
    );
  }
}


// ============================================================
// INTERNAL EXTRACTION STATS
// ============================================================

const stats = {
  collection:
    rows.filter(
      row =>
        row.statuts ===
        "collection"
    ).length,

  wishlist:
    rows.filter(
      row =>
        row.statuts ===
        "wishlist"
    ).length,

  fiches:
    detailsById.size,

  prix_absents:
    rows.filter(
      row =>
        row.prix ===
        null
    ).length,

  annees_absentes:
    rows.filter(
      row =>
        row.annee_sortie ===
        null
    ).length,

  genres_absents:
    rows.filter(
      row =>
        row.genre ===
        null
    ).length,
};


// ============================================================
// FINAL OUTPUT
// ============================================================

return [
  {
    json: {
      complete:
        true,

      extracted_at:
        manifest.extracted_at,

      rows,

      stats,

      public_stats:
        publicStats,

      warnings,
    },
  },
];

// Mode: Run Once for All Items.
//
// Use the complete validated dataset after the table insertion succeeds.
const source = $('Stat4').first().json;

if (source.complete !== true || !Array.isArray(source.rows)) {
  throw new Error(
    'Les données complètes de Stat4 sont indisponibles.'
  );
}

// ============================================================
// PUBLIC MYLUDO STATISTICS
// ============================================================

function optionalCount(value) {
  if (
    (typeof value !== "number" && typeof value !== "string") ||
    (typeof value === "string" && value.trim() === "")
  ) {
    return null;
  }

  const number = Number(value);
  return Number.isSafeInteger(number) && number >= 0 ? number : null;
}

function normalizePublicStats(value) {
  const isRecord = item =>
    item !== null && typeof item === "object" && !Array.isArray(item);
  const raw = isRecord(value) ? value : {};
  const readCounters = (group, keys) => Object.fromEntries(
    keys.map(key => [key, optionalCount(isRecord(group) ? group[key] : null)])
  );

  const duration = readCounters(raw.duration, [
    "years", "months", "days", "hours", "minutes"
  ]);
  const parties = readCounters(raw.parties, ["total", "cooperation", "solo"]);
  const details = readCounters(raw.details, ["games", "places", "h_index"]);
  const ready = raw.ready === true &&
    [duration, parties, details].every(group =>
      Object.values(group).every(number => number !== null)
    ) && Array.isArray(raw.top10);

  return {
    ...raw,
    ready,
    reason: ready ? null : String(raw.reason || "Statistiques absentes ou incomplètes"),
    duration,
    parties,
    details,
    top10: Array.isArray(raw.top10) ? raw.top10.filter(isRecord) : []
  };
}

function collectStatsWarnings(existing, publicStats) {
  const warnings = Array.isArray(existing) ? [...existing] : [];
  if (!publicStats.ready) {
    const warning = "Statistiques MyLudo indisponibles ou incomplètes : " + publicStats.reason;
    if (!warnings.includes(warning)) warnings.push(warning);
  }
  return warnings;
}

const publicStats = normalizePublicStats(source.public_stats);
const warnings = collectStatsWarnings(source.warnings, publicStats);

// ============================================================
// HELPERS
// ============================================================

const clean = value =>
  String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();

const normalize = value =>
  clean(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();

// ============================================================
// CATEGORY NORMALIZATION
// ============================================================

const categoryMap = new Map([
  ['jeu de base', 'Jeux de base'],
  ['jeux de base', 'Jeux de base'],
  ['basegame', 'Jeux de base'],

  ['extension', 'extension'],
  ['standalone', 'standalone'],
  ['accessoire', 'accessoire'],
  ['goodie', 'goodie'],

  ['demo', 'démo'],
  ['démo', 'démo'],

  ['autre', 'autre'],
]);

// ============================================================
// GROUP CREATION
// ============================================================

function createGroup() {
  return {
    categories: {
      'Jeux de base': 0,
      extension: 0,
      standalone: 0,
      accessoire: 0,
      goodie: 0,
      'démo': 0,
      autre: 0,
    },

    genres: new Map(),
    genreLabels: new Map(),

    decades: new Map(),

    total: 0,

    priceCents: 0,
    knownPrices: 0,
    missingPrices: 0,
  };
}

const groups = {
  collection: createGroup(),
  wishlist: createGroup(),
};

// ============================================================
// ANALYZE DATA TABLE ROWS
// ============================================================

for (const row of source.rows) {
  const status = normalize(row.statuts);

  if (!Object.hasOwn(groups, status)) {
    throw new Error(
      `Statut inconnu pour "${row.Nom}" : ${row.statuts}`
    );
  }

  const group = groups[status];

  group.total++;

  // ==========================================================
  // CATEGORY
  // ==========================================================

  const category =
    categoryMap.get(
      normalize(row.categorie)
    ) ?? 'autre';

  group.categories[category]++;

  // ==========================================================
  // GENRES
  // ==========================================================

  const values = Array.isArray(row.genre)
    ? row.genre
    : String(row.genre ?? '').split('|');

  const seen = new Set();

  for (const value of values) {
    const label = clean(value);

    if (!label) {
      continue;
    }

    const key = normalize(label);

    // Count each genre only once per game.
    if (seen.has(key)) {
      continue;
    }

    seen.add(key);

    if (!group.genreLabels.has(key)) {
      group.genreLabels.set(
        key,
        label
      );
    }

    group.genres.set(
      key,
      (group.genres.get(key) ?? 0) + 1
    );
  }

  if (!seen.size) {
    group.genreLabels.set(
      'sans genre',
      'Sans genre'
    );

    group.genres.set(
      'sans genre',
      (group.genres.get('sans genre') ?? 0) + 1
    );
  }

  // ==========================================================
  // PRICE
  // ==========================================================

  const missingPrice =
    row.prix === null ||
    row.prix === undefined ||
    clean(row.prix) === '';

  if (missingPrice) {
    group.missingPrices++;
  } else {
    const price = Number(row.prix);
    const cents = Math.round(price * 100);

    if (
      !Number.isFinite(price) ||
      price < 0 ||
      !Number.isSafeInteger(cents)
    ) {
      throw new Error(
        `Prix invalide pour "${row.Nom}" : ${row.prix}`
      );
    }

    group.priceCents += cents;

    if (!Number.isSafeInteger(group.priceCents)) {
      throw new Error(
        'Total des prix trop grand'
      );
    }

    group.knownPrices++;
  }

  // ==========================================================
  // RELEASE DECADE
  // ==========================================================

  let decade = 'Sans année';

  const missingYear =
    row.annee_sortie === null ||
    row.annee_sortie === undefined ||
    clean(row.annee_sortie) === '';

  if (!missingYear) {
    const year = Number(
      row.annee_sortie
    );

    if (
      !Number.isInteger(year) ||
      year < 1000 ||
      year > 2999
    ) {
      throw new Error(
        `Année invalide pour "${row.Nom}" : ${row.annee_sortie}`
      );
    }

    decade = String(
      Math.floor(year / 10) * 10
    );
  }

  group.decades.set(
    decade,
    (group.decades.get(decade) ?? 0) + 1
  );
}

// ============================================================
// PRICE FORMAT
// ============================================================

const currency = new Intl.NumberFormat(
  'fr-FR',
  {
    style: 'currency',
    currency: 'EUR',
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }
);

// ============================================================
// FORMAT COLLECTION / WISHLIST
// ============================================================

function formatGroup(group) {
  const genres = [...group.genres]
    .map(([key, count]) => [
      group.genreLabels.get(key),
      count,
    ])
    .sort(
      (a, b) =>
        b[1] - a[1] ||
        a[0].localeCompare(
          b[0],
          'fr'
        )
    );

  const decades = [
    ...group.decades.entries(),
  ].sort((a, b) => {
    if (a[0] === 'Sans année') {
      return 1;
    }

    if (b[0] === 'Sans année') {
      return -1;
    }

    return Number(b[0]) - Number(a[0]);
  });

  const formattedPrice =
    group.knownPrices > 0 ||
    group.total === 0
      ? currency
          .format(
            group.priceCents / 100
          )
          .replace(
            /[\u00a0\u202f]/g,
            ' '
          )
      : null;

  return {
    Total: group.total,

    ...group.categories,

    genre:
      Object.fromEntries(genres),

    prix:
      formattedPrice,

    sans_prix:
      group.missingPrices,

    prix_connus:
      group.knownPrices,

    'décennie':
      Object.fromEntries(decades),
  };
}

// ============================================================
// TOTAL PLAY TIME
// ============================================================

function formatDuration(duration) {
  // A partial duration cannot be presented as a known total.
  const keys = ["years", "months", "days", "hours", "minutes"];
  if (!duration || keys.some(key => optionalCount(duration[key]) === null)) {
    return null;
  }

  const parts = [];

  const years =
    Number(duration.years) || 0;

  const months =
    Number(duration.months) || 0;

  const days =
    Number(duration.days) || 0;

  const hours =
    Number(duration.hours) || 0;

  const minutes =
    Number(duration.minutes) || 0;

  if (years > 0) {
    parts.push(
      `${years} ${
        years === 1
          ? 'an'
          : 'ans'
      }`
    );
  }

  if (months > 0) {
    parts.push(
      `${months} mois`
    );
  }

  if (days > 0) {
    parts.push(
      `${days} j`
    );
  }

  if (hours > 0) {
    parts.push(
      `${hours} h`
    );
  }

  if (
    minutes > 0 ||
    parts.length === 0
  ) {
    parts.push(
      `${minutes} min`
    );
  }

  return parts.join(' ');
}

// ============================================================
// MYLUDO PUBLIC STATISTICS
// ============================================================

const myLudoStats = {
  // ----------------------------------------------------------
  // TOTAL PLAY TIME
  // ----------------------------------------------------------

  duree_totale:
    formatDuration(
      publicStats.duration
    ),

  duree_totale_detail: {
    annees:
      publicStats.duration.years,

    mois:
      publicStats.duration.months,

    jours:
      publicStats.duration.days,

    heures:
      publicStats.duration.hours,

    minutes:
      publicStats.duration.minutes,
  },

  // ----------------------------------------------------------
  // PLAYS
  // ----------------------------------------------------------

  parties: {
    total:
      publicStats.parties.total,

    cooperation:
      publicStats.parties.cooperation,

    solo:
      publicStats.parties.solo,
  },

  // ----------------------------------------------------------
  // DETAILS
  // ----------------------------------------------------------

  details: {
    jeux:
      publicStats.details.games,

    lieux:
      publicStats.details.places,

    h_index:
      publicStats.details.h_index,
  },

  // ----------------------------------------------------------
  // TOP 10 GAMES
  // ----------------------------------------------------------

  top_10:
    publicStats.top10
      .map((entry, index) => ({
        rang:
          Number(entry.rank) ||
          index + 1,

        id:
          entry.id ?? null,

        jeu:
          clean(entry.name) ||
          'Jeu inconnu',

        duree_minutes:
          optionalCount(entry.duration_minutes),

        parties:
          optionalCount(entry.plays),

        url:
          entry.url ?? null,
      }))
      .sort(
        (a, b) =>
          a.rang - b.rang
      ),
};

// ============================================================
// FINAL SINGLE OUTPUT
// ============================================================

return [
  {
    json: {
      Collection:
        formatGroup(
          groups.collection
        ),

      wishlist:
        formatGroup(
          groups.wishlist
        ),

      Statistiques:
        myLudoStats,

      warnings,
    },
  },
];

let data = $('HTTP Request').first().json;

if (typeof data.data === 'string') {
  data = JSON.parse(data.data);
} else if (data.data?.collection) {
  data = data.data;
}

if (!Array.isArray(data.collection) || !data.statistiques) {
  throw new Error('Invalid extraction result.');
}

return data.collection.map(row => {
  if (
    !row.Titre ||
    !['film', 'série'].includes(row.Genre) ||
    !['dans ma bibliothèque', 'liste de souhait'].includes(row.Statut) ||
    !row.Categorie ||
    !(
      row.Prix === null ||
      (
        typeof row.Prix === 'number' &&
        Number.isFinite(row.Prix) &&
        row.Prix >= 0
      )
    )
  ) {
    throw new Error(
      'Invalid collection entry: ' + (row.Titre || 'unknown')
    );
  }

  return {
    json: {
      Titre: row.Titre,
      Genre: row.Genre,
      Statut: row.Statut,
      Categorie: row.Categorie,
      Prix: row.Prix,
    },
  };
});

// Read the complete extraction from HTTP Request.
let data = $('HTTP Request').first().json;

if (typeof data.data === 'string') {
  data = JSON.parse(data.data);
} else if (data.data?.collection) {
  data = data.data;
}

if (!Array.isArray(data.collection) || !data.statistiques) {
  throw new Error('Invalid extraction result.');
}

// Count each edition under its complete format label.
function countFormats(rows) {
  const result = {
    DVD: 0,
    'Blu-ray': 0,
  };

  for (const row of rows) {
    result[row.Categorie] =
      (result[row.Categorie] || 0) + 1;
  }

  return result;
}

// Sum known prices in cents to avoid rounding errors.
function calculatePrices(rows) {
  const known = rows.filter(row =>
    typeof row.Prix === 'number' &&
    Number.isFinite(row.Prix) &&
    row.Prix >= 0
  );

  const total =
    known.length > 0 || rows.length === 0
      ? known.reduce(
          (sum, row) => sum + Math.round(row.Prix * 100),
          0
        ) / 100
      : null;

  return {
    total,
    missing: rows.length - known.length,
  };
}

// Build separate summaries for movies and series.
function summarize(genre) {
  const rows = data.collection.filter(
    row => row.Genre === genre
  );

  const owned = rows.filter(
    row => row.Statut === 'dans ma bibliothèque'
  );

  const wishlist = rows.filter(
    row => row.Statut === 'liste de souhait'
  );

  const ownedPrices = calculatePrices(owned);
  const wishlistPrices = calculatePrices(wishlist);

  return {
    possession: owned.length,
    liste_souhait: wishlist.length,

    formats_possession: countFormats(owned),
    formats_souhait: countFormats(wishlist),

    prix_total: ownedPrices.total,
    prix_manquants: ownedPrices.missing,

    prix_souhait: wishlistPrices.total,
    prix_souhait_manquants: wishlistPrices.missing,
  };
}

// Calculate the total price of all owned editions.
const ownedCollection = data.collection.filter(
  row => row.Statut === 'dans ma bibliothèque'
);

const totalPrices = calculatePrices(ownedCollection);

// Return a single item for the following Google Sheets nodes.
return [{
  json: {
    statistiques_site: data.statistiques,

    prix_total: totalPrices.total,
    prix_manquants: totalPrices.missing,

    films: summarize('film'),
    series: summarize('série'),

    collection: data.collection,
  },
}];

