parameters.jsonBody:
={{
  {
    code: `export default async function ({ page, context = {} }) {
      const output = (data) => ({
        data: {
          date_verification: new Date().toISOString(),
          ...data
        },
        type: 'application/json'
      });

      try {
        let cookies = context.cookies || [];

        if (typeof cookies === 'string') {
          try {
            cookies = JSON.parse(cookies);
          } catch {
            return output({
              statut_session: 'erreur',
              erreur: 'cookie_dvd contient un JSON invalide.'
            });
          }
        }

        if (!Array.isArray(cookies) || cookies.length === 0) {
          return output({
            statut_session: 'invalide',
            raison: 'Aucun cookie Blu-ray.com fourni.'
          });
        }

        const filteredCookies = cookies
          .filter((cookie) => {
            const domain = String(cookie.domain || '').toLowerCase();

            return (
              cookie.name &&
              (
                domain === 'blu-ray.com' ||
                domain === '.blu-ray.com' ||
                domain.endsWith('.blu-ray.com')
              )
            );
          })
          .map((cookie) => ({
            name: String(cookie.name),
            value: String(cookie.value ?? ''),
            domain: cookie.domain || '.blu-ray.com',
            path: cookie.path || '/',
            secure: cookie.secure !== false,
            httpOnly: Boolean(cookie.httpOnly)
          }));

        const cookieNames = new Set(
          filteredCookies.map((cookie) => cookie.name)
        );

        if (
          !cookieNames.has('bbuserid') ||
          !cookieNames.has('bbpassword')
        ) {
          return output({
            statut_session: 'invalide',
            raison: 'Les cookies bbuserid et/ou bbpassword sont absents.'
          });
        }

        await page.setCookie(...filteredCookies);

        await page.setViewport({
          width: 1280,
          height: 900
        });

        await page.setExtraHTTPHeaders({
          'Accept-Language': 'fr-FR,fr;q=0.9,en;q=0.8'
        });

        const response = await page.goto(
          'https://www.blu-ray.com/community/settings.php',
          {
            waitUntil: 'domcontentloaded',
            timeout: 60000
          }
        );

        if (!response) {
          return output({
            statut_session: 'erreur',
            erreur: 'Aucune réponse HTTP reçue de Blu-ray.com.'
          });
        }

        const check = await page.evaluate(() => {
          const text = String(
            document.body?.innerText || ''
          )
            .replace(/\\s+/g, ' ')
            .trim();

          const links = Array.from(
            document.querySelectorAll('a[href]')
          );

          const hasLogout = links.some((a) => {
            const label = String(a.textContent || '')
              .trim()
              .toLowerCase();

            const href = String(
              a.getAttribute('href') || ''
            ).toLowerCase();

            return (
              label === 'logout' ||
              label === 'log out' ||
              href.includes('logout')
            );
          });

          const notLogged =
            /not logged in/i.test(text) ||
            /you need to be logged in/i.test(text);

          return {
            hasLogout,
            notLogged,
            title: document.title || ''
          };
        });

        if (check.notLogged) {
          return output({
            statut_session: 'invalide',
            raison: 'Blu-ray.com refuse les cookies : session non connectée.',
            http_status: response.status()
          });
        }

        if (check.hasLogout) {
          return output({
            statut_session: 'valide',
            raison: 'Session Blu-ray.com valide.',
            http_status: response.status()
          });
        }

        return output({
          statut_session: 'erreur',
          erreur: 'Impossible de confirmer la session avec certitude.',
          http_status: response.status(),
          titre_page: check.title
        });

      } catch (error) {
        return output({
          statut_session: 'erreur',
          erreur: error instanceof Error
            ? error.message
            : String(error)
        });
      }
    }`,
    context: {
      cookies: $json.cookie_dvd
    }
  }
}}

