{
  code: `export default async function ({ page, context }) {
    const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

    let cookies = context.cookies || [];

    if (typeof cookies === "string") {
      cookies = JSON.parse(cookies);
    }

    if (!Array.isArray(cookies)) {
      throw new Error("Cookies Gleeph invalides.");
    }

    await page.setUserAgent(
      "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122 Safari/537.36"
    );

    await page.setViewport({ width: 1440, height: 1000 });

    if (cookies.length) {
      await page.setCookie(...cookies);
    }

    await page.goto(context.url, {
      waitUntil: "domcontentloaded",
      timeout: 90000
    });

    try {
      await page.waitForSelector(
        "div[class*='priceOfLibrary_textContainer']",
        { timeout: 60000 }
      );
    } catch {}

    await sleep(1500);

    const html = await page.content();

    return {
      url: page.url(),
      html
    };
  }`,
  context: {
    url: "https://www.gleeph.com/profile/stats",
    cookies: $('Configuration Globale').first().json.cookie_gleeph
  }
}
}}

parameters.jsCode:
const input = $input.first().json;

const html =
  input.html ||
  input.data?.html ||
  input.body?.html ||
  "";

if (!html) {
  throw new Error("Aucun HTML reçu depuis HTTP Request3");
}

let match = html.match(
  /<span[^>]*>\s*La bibliothèque vaut\s*<\/span>\s*<span[^>]*>\s*([^<]+?)\s*<\/span>/i
);

if (!match) {
  throw new Error("La valeur 'La bibliothèque vaut' est introuvable");
}

const prixTexte = match[1]
  .replace(/&nbsp;/gi, " ")
  .replace(/&euro;/gi, "€")
  .trim();

const prixNombre = Number(
  prixTexte
    .replace(/[^0-9,.-]/g, "")
    .replace(",", ".")
);

return [
  {
    json: {
      Prix_Gleeph: prixTexte,
      Prix_Gleeph_nombre: prixNombre
    }
  }
];

// yt-dlp reports the final path as JSON after conversion or reuse of an existing MP3.
return $input.all().map((item, index) => {
  const exitCode = Number(item.json.code ?? item.json.exitCode ?? 0);
  if (exitCode !== 0) throw new Error(`Audio download failed with exit code ${exitCode}.`);
  const lines = String(item.json.stdout ?? '').split(/\r?\n/);
  const marker = lines.filter(line => line.startsWith('N8N_FILE:')).at(-1);
  if (!marker) throw new Error('The downloader did not return a final audio path.');
  let hostPath;
  try { hostPath = JSON.parse(marker.slice('N8N_FILE:'.length)); }
  catch { throw new Error('The downloader returned an invalid JSON path.'); }
  if (typeof hostPath !== 'string') throw new Error('The audio path must be a string.');
  const filename = hostPath.split('/').at(-1);
  if (!filename || !/\.mp3$/i.test(filename)) throw new Error('The final audio file is not an MP3.');
  return {json: {file_path: `/home/node/.n8n-files/${filename}`}, pairedItem: {item:index}};
});
